/* 자동 생성 — 개념카드/굽기.py. 손으로 고치지 말 것 */
window.CARD={"#1":{"묶음":[{"머리":"유체의 정의와 연속체","줄":[{"t":"유체: 액체와 기체. 고체는 유체가 아니다.","src":"기출 2023-26"},{"t":"연속체 가정: 원자 단위로는 떨어져 있어도 구멍 없는 연속체로 보고 해석한다.","src":"기출 2022-27"},{"t":"포화압력: 주어진 온도에서 순수 물질이 상변화를 하는 압력.","src":"기출 2022-27"},{"t":"위치에너지: 중력장 안에서 고도에 따라 시스템이 가지는 에너지. 속도에 따른 에너지는 운동에너지.","src":"기출 2022-27"},{"t":"유체의 종류: 뉴턴 유체(전단응력이 속도경사에 비례), 비뉴턴 유체, 이상유체(비점성·비압축성), 실제유체(점성 있음).","src":"보충"}]},{"머리":"밀도·비중·비체적·단위중량","줄":[{"t":"밀도 ρ: 단위 체적당 질량. 물은 4℃에서 1,000 kg/m³ = 1 g/cm³(최대).","src":"보충"},{"t":"단위중량(비중량) γ = ρg. 물의 γ = 9,800 N/m³ = 1,000 kgf/m³.","src":"보충"},{"t":"비중 S: 어떤 물질의 밀도(또는 단위중량)를 4℃ 물의 밀도(단위중량)로 나눈 값. 단위가 없다.","src":"보충"},{"t":"비체적 v = 1/ρ. 단위 질량이 차지하는 체적.","src":"보충"},{"t":"비중 풀이 순서: 중량을 체적으로 나눠 γ를 구한다 → 9,800 N/m³로 나눈다. 예) 5 m³, 98,000 N이면 γ = 19,600 → 비중 2.0.","src":"기출 2026-26"},{"t":"수중 무게로 비중 구하기: 비중 = 공기 중 무게 ÷ (공기 중 무게 − 수중 무게). 예) 2 kg, 0.5 kg → 2 ÷ 1.5 = 1.33.","src":"기출 2021-27"},{"t":"수중 무게 감소분 = 부력 = 밀어낸 물의 무게(아르키메데스 원리).","src":"보충"}]},{"머리":"점성계수와 동점성계수","줄":[{"t":"뉴턴의 점성법칙: 전단응력 τ = μ·du/dy. 점성계수 μ는 전단응력과 속도경사 사이의 비례상수.","src":"기출 2021-26"},{"t":"점성: 유체에 전단응력이 작용할 때 변형에 저항하는 성질.","src":"기출 2024-27"},{"t":"액체: 온도가 오르면 점성계수가 감소한다. 기체: 온도가 오르면 점성계수가 증가한다.","src":"기출 2021-26"},{"t":"동점성계수 ν = μ/ρ. 점성계수를 밀도로 나눈 값이다(유속으로 나누는 것이 아니다).","src":"기출 2021-26"},{"t":"점성계수 μ의 단위: Pa·s = N·s/m² = kg/(m·s). CGS는 poise(P) = g/(cm·s). 1 P = 0.1 Pa·s.","src":"기출 2022-26"},{"t":"동점성계수 ν의 단위: m²/s. CGS는 stokes(St) = cm²/s. 1 St = 10⁻⁴ m²/s.","src":"기출 2022-26"},{"t":"점성계수와 동점성계수는 단위가 다르다.","src":"기출 2024-27"},{"t":"동점성계수 계산(CGS): ν(St) = μ(P) ÷ 밀도(g/cm³). 예) 0.8 P, 비중 1.1 → 0.8 ÷ 1.1 = 0.727 St.","src":"기출 2022-26"},{"t":"점성계수 계산(SI): μ = ν × ρ. 예) ν 0.002 m²/s, 비중 1.1(ρ 1,100) → 2.2 N·s/m².","src":"기출 2023-27"},{"t":"벽면 전단응력에서 μ 구하기: 속도분포 u(y)를 y로 미분해 바닥(y=0)의 du/dy를 구한 뒤 μ = τ ÷ (du/dy). 예) u = 5y − y², du/dy(0) = 5, τ 0.01 Pa → μ = 0.002 Pa·s = 2×10⁻³.","src":"기출 2025-28"}]},{"머리":"차원(MLT계와 FLT계)","줄":[{"t":"점성계수 μ: [ML⁻¹T⁻¹] = [FL⁻²T].","src":"보충"},{"t":"동점성계수 ν: [L²T⁻¹]. MLT와 FLT에서 같다.","src":"기출 2024-27"},{"t":"표면장력 σ: [FL⁻¹] = [MT⁻²].","src":"기출 2021-33"},{"t":"단위중량 γ: [FL⁻³] = [ML⁻²T⁻²].","src":"기출 2021-33"},{"t":"밀도 ρ: [FL⁻⁴T²] = [ML⁻³]. 단위중량의 차원이 아니다.","src":"기출 2021-33"},{"t":"에너지(일): [FL] = [ML²T⁻²].","src":"기출 2021-33"},{"t":"힘 [MLT⁻²]=[F], 압력 [FL⁻²], 속도 [LT⁻¹], 가속도 [LT⁻²], 유량 [L³T⁻¹].","src":"보충"}]},{"머리":"표면장력과 모세관 현상","줄":[{"t":"모세관 상승높이(원형관): h = 4σcosθ ÷ (γd). σ 표면장력, θ 접촉각, d 관 지름.","src":"기출 2021-34"},{"t":"상승높이는 표면장력 σ에 비례하고 관의 지름 d에 반비례한다. 밀도(단위중량)와 중력가속도에도 반비례한다.","src":"기출 2021-34"},{"t":"대기압 Pa를 고려한 상승높이: h = 4σcosθ ÷ (γd) − Pa/γ.","src":"기출 2024-30"},{"t":"평행한 두 유리판 사이의 상승높이: h = 2σcosθ ÷ (γb). b는 판 사이 간격. 간격이 좁을수록 높이 올라간다(문항에 간격 조건 누락, 정답은 약 0.3 cm).","src":"기출 2026-27"},{"t":"물과 유리의 접촉각은 거의 0°(cosθ≈1)라 물은 올라가고, 수은은 접촉각이 커서 내려간다.","src":"보충"},{"t":"물의 표면장력: 약 0.073 N/m(20℃, 공기 접촉).","src":"보충"}]},{"머리":"이상기체 상태방정식","줄":[{"t":"Boyle의 법칙: 일정한 온도에서 기체의 부피는 압력에 반비례한다(PV = 일정).","src":"기출 2025-26"},{"t":"Charles의 법칙: 일정한 압력에서 기체의 부피는 절대온도에 비례한다(V/T = 일정).","src":"기출 2025-26"},{"t":"Avogadro의 법칙: 일정한 온도와 압력에서 같은 부피 속의 기체 분자 수는 같다.","src":"기출 2025-26"},{"t":"상태방정식: PV = nRT = (m/M)RT, P = ρRT. R은 특정 이상기체마다 정해진 값(R = 일반기체상수 ÷ 분자량).","src":"기출 2025-26"},{"t":"이상기체의 음속 c = √(kRT). 온도의 함수이며 압력의 함수가 아니다.","src":"기출 2022-27"},{"t":"공기질량 풀이 순서: 실 체적 V = 가로×세로×높이 → T를 K로(℃+273) → m = PV ÷ (RT). 예) 8×8×3 = 192 m³, P 100 kPa, T 298 K, 공기 R 0.287 kJ/kg·K → 약 224.5 kg.","src":"기출 2022-29"},{"t":"일반기체상수 R = 8.314 J/mol·K, 공기의 기체상수 R = 287 J/kg·K, 공기 분자량 약 29.","src":"보충"},{"t":"표준상태(0℃, 1기압)에서 기체 1 mol의 부피는 22.4 L.","src":"보충"}]},{"머리":"엔트로피","줄":[{"t":"엔트로피: 물질계가 흡수하는 열량과 절대온도의 비로 정의한다(dS = δQ/T).","src":"기출 2025-27"},{"t":"엔트로피는 무질서 또는 에너지의 분산 정도를 나타내는 상태함수다.","src":"기출 2025-27"},{"t":"자연계의 상태변화는 엔트로피가 증가하는 방향으로 일어난다.","src":"기출 2025-27"},{"t":"가역과정은 엔트로피가 변하지 않고(고립계), 비가역과정은 엔트로피가 증가한다.","src":"기출 2025-27"}]}],"함정":[{"x":"동점성계수는 점성계수를 유속으로 나눈 값이다.","o":"동점성계수는 점성계수를 밀도로 나눈 값이다(ν = μ/ρ).","src":"기출 2021-26"},{"x":"점성계수와 동점성계수의 단위는 같다.","o":"점성계수는 Pa·s, 동점성계수는 m²/s로 다르다.","src":"기출 2024-27"},{"x":"표면장력: [FL^-2]","o":"표면장력의 차원은 [FL⁻¹].","src":"기출 2021-33"},{"x":"점성계수: [L^2T^-1]","o":"[L²T⁻¹]은 동점성계수의 차원. 점성계수는 [FL⁻²T].","src":"기출 2021-33"},{"x":"단위중량: [FL^-4T^2]","o":"[FL⁻⁴T²]은 밀도의 차원. 단위중량은 [FL⁻³].","src":"기출 2021-33"},{"x":"모세관 현상의 상승 높이는 물의 밀도에 비례한다.","o":"상승높이는 밀도(단위중량)에 반비례한다.","src":"기출 2021-34"},{"x":"모세관 현상의 상승 높이는 중력가속도에 비례한다.","o":"중력가속도에 반비례한다.","src":"기출 2021-34"},{"x":"모세관 현상의 상승 높이는 물의 표면장력에 반비례한다.","o":"표면장력에 비례한다.","src":"기출 2021-34"},{"x":"이상기체에서의 음속은 압력의 함수이다.","o":"이상기체의 음속 c = √(kRT)는 온도의 함수다.","src":"기출 2022-27"},{"x":"엔트로피는 가역반응이면 증가하고 비가역반응이면 불변이다.","o":"가역과정은 불변, 비가역과정은 증가한다.","src":"기출 2025-27"},{"x":"2023-26 보기 ㄱ. 고체가 유체에 해당한다.","o":"유체는 액체와 기체이며 고체는 포함되지 않는다.","src":"기출 2023-26"}]},"#2":{"묶음":[{"머리":"정지 유체의 압력","줄":[{"t":"정지 유체 안의 압력 P = P₀ + γh. 자유수면 아래 한 점의 압력은 수심이 깊어질수록 증가한다.","src":"기출 2025-29"},{"t":"정지 유체의 압력은 깊이와 유체의 단위중량으로 정해지고 용기 모양과 무관하다(파스칼의 역설).","src":"기출 2025-29"},{"t":"압력의 등방성: 정지 유체의 한 점에 작용하는 압력은 모든 방향에서 같다.","src":"기출 2025-29"},{"t":"유체가 접촉면에 주는 압력은 면에 수직으로 작용한다(경사면에도 수직).","src":"기출 2025-29"},{"t":"압력은 단위중량(밀도)에 비례한다. 수은 γ = 13.6 × γ물.","src":"기출 2025-29"}]},{"머리":"압력의 종류와 단위","줄":[{"t":"절대압력 = 대기압 + 게이지압력. 진공압 = 대기압 − 절대압력.","src":"보충"},{"t":"1 atm = 101.325 kPa = 760 mmHg = 10.33 mH₂O = 1.0332 kgf/cm².","src":"보충"},{"t":"1 kgf/cm² = 10 mH₂O = 98.07 kPa. 예) 2.2 kgf/cm² = 22 mH₂O(압력수두).","src":"기출 2024-33"},{"t":"압력수두 h = P/γ.","src":"보충"}]},{"머리":"마노미터·평면에 작용하는 힘·부력","줄":[{"t":"U자관 마노미터: 같은 유체로 이어진 같은 높이의 압력은 같다는 원리로 압력차를 구한다. P₁ − P₂ = (γ액 − γ물)h.","src":"보충"},{"t":"수면 아래 평면에 작용하는 전압력 F = γ·h_c·A. h_c는 도심까지 깊이, A는 면적.","src":"보충"},{"t":"부력 F_B = γ·V(잠긴 체적). 부력은 밀어낸 유체의 무게와 같다.","src":"보충"}]}],"함정":[{"x":"유체의 압력은 유체와 접촉하는 경사면에 수평으로만 작용한다.","o":"압력은 접촉면에 수직으로 작용한다.","src":"기출 2025-29"},{"x":"자유수면을 갖는 경우 수면 아래 압력은 밀도에 반비례한다.","o":"수면 아래 압력은 밀도(단위중량)에 비례한다(P = γh).","src":"기출 2025-29"},{"x":"동일한 높이의 개방된 용기에 수은을 가득 채우면 용기형상에 따라 바닥에서 압력이 달라진다.","o":"바닥 압력은 깊이와 단위중량만으로 정해져 용기 형상과 무관하다.","src":"기출 2025-29"}]},"#3":{"묶음":[{"머리":"흐름의 분류","줄":[{"t":"정상류: 한 점에서 유동 특성이 시간에 따라 변하지 않는 흐름(∂U/∂t = 0). 모든 점에서 변하지 않는 흐름을 말한다.","src":"기출 2026-31"},{"t":"비정상류: 유동 특성이 시간에 따라 변하는 흐름(∂U/∂t ≠ 0).","src":"기출 2025-32"},{"t":"등류: 유동 특성이 장소(거리)에 따라 변하지 않는 흐름(∂U/∂x = 0). 부등류: 장소에 따라 변하는 흐름(∂U/∂x ≠ 0).","src":"기출 2025-32"},{"t":"상류(常流): 프루드수 Fr < 1. 사류(射流): Fr > 1. 한계류: Fr = 1. 프루드수 Fr = V/√(gh).","src":"기출 2025-32"},{"t":"사류·상류·한계류는 프루드수로 가른다. 레이놀즈수로 알 수 있는 흐름은 층류·난류·천이류이다.","src":"기출 2023-34"}]},{"머리":"레이놀즈수","줄":[{"t":"레이놀즈수 Re = ρVD/μ = VD/ν. 관성력과 점성력의 비.","src":"기출 2022-31"},{"t":"원형관 기준: 층류 Re < 2,100(약 2,000), 천이류 약 2,100~4,000, 난류 Re > 4,000.","src":"기출 2025-32"},{"t":"레이놀즈수로 판별하는 흐름: 층류, 난류, 천이류. 사류는 해당하지 않는다.","src":"기출 2026-29"},{"t":"Re 풀이 순서: Q를 m³/s로 → 유속 V = Q ÷ (πD²/4) → Re = VD/ν. 예) 250 mm 관, 40 L/s → V = 0.815 m/s. 정답 1,698은 ν ≈ 1.2×10⁻⁴ m²/s일 때 나온다(문항에 동점성계수 조건 누락, 추정).","src":"기출 2022-31"}]},{"머리":"연속방정식·유량","줄":[{"t":"연속방정식(질량보존): ρ₁A₁V₁ = ρ₂A₂V₂. 비압축성이면 Q = AV = 일정, A₁V₁ = A₂V₂.","src":"기출 2023-31"},{"t":"유량 Q = AV = (πD²/4)V. 지름이 같은 비율로 변하면 유속은 지름 제곱에 반비례한다.","src":"기출 2024-26"},{"t":"예) 지름 100 mm, 5 m/s → Q = (π × 0.1²/4) × 5 = 0.039 m³/s.","src":"기출 2024-26"},{"t":"예) 30 cm 관 1.5 m/s → 20 cm 관: V₂ = 1.5 × (30/20)² = 3.375 m/s.","src":"기출 2023-31"},{"t":"예) 200 L/min = 3.333×10⁻³ m³/s. 40 mm 호스 유속 2.65 m/s, 20 mm로 줄이면 10.61 m/s → 증가분 약 7.95 m/s.","src":"기출 2024-34"},{"t":"질량보존 법칙을 유체 흐름에 적용한 식이 연속방정식이다. 베르누이 방정식은 에너지보존 법칙을 적용한 식이다.","src":"기출 2026-28"}]},{"머리":"베르누이 방정식","줄":[{"t":"베르누이 방정식: P/γ + V²/2g + Z = 일정(압력수두 + 속도수두 + 위치수두).","src":"기출 2023-29"},{"t":"적용 조건: 정상류, 비압축성, 비점성(마찰 없음), 같은 유선을 따르는 흐름.","src":"기출 2021-32"},{"t":"비정상류와 압축성 유체의 흐름은 적용조건이 아니다.","src":"기출 2022-28"},{"t":"이상유체 전수두 = 위치수두 + 압력수두 + 속도수두. 마찰손실수두는 전수두의 구성이 아니다.","src":"기출 2023-29"},{"t":"동수경사선(HGL): 압력수두와 위치수두의 합을 연결한 선. 에너지선(EGL): 여기에 속도수두를 더한 선.","src":"기출 2026-28"},{"t":"실제유체는 손실수두를 더한다: P₁/γ + V₁²/2g + Z₁ = P₂/γ + V₂²/2g + Z₂ + h_L.","src":"보충"}]},{"머리":"베르누이 응용(피토관·사출)","줄":[{"t":"피토관 유속: V = √(2g·h·(S액/S물 − 1)). 마노미터 액체 수은 비중 13.6.","src":"기출 2025-30"},{"t":"예) 수은 액면차 0.5 m → V = √(2×9.8×0.5×12.6) = 약 11.1 m/s.","src":"기출 2025-30"},{"t":"경사 사출(각 θ)의 최대 수직상승높이 H = (V·sinθ)² ÷ 2g. 예) 9.8 m/s, 45° → (6.93)² ÷ 19.6 = 2.45 m. 관 지름은 계산에 쓰이지 않는다.","src":"기출 2022-30"},{"t":"토리첼리: 오리피스 유속 V = √(2gh).","src":"보충"}]}],"함정":[{"x":"베르누이 방정식 제한조건: 비정상류 흐름","o":"정상류 흐름에서만 적용한다.","src":"기출 2021-32"},{"x":"베르누이 방정식의 가정조건: 압축성 유체의 흐름이다.","o":"비압축성 유체의 흐름이다.","src":"기출 2022-28"},{"x":"전수두(total head)를 구성하는 수두: 마찰손실수두","o":"위치수두, 압력수두, 속도수두의 합이다(마찰손실수두는 구성이 아님).","src":"기출 2023-29"},{"x":"베르누이 방정식은 질량보존법칙을 유체의 흐름에 적용한 것이다.","o":"베르누이 방정식은 에너지보존법칙이다. 질량보존은 연속방정식.","src":"기출 2026-28"},{"x":"난류: Re < 200","o":"난류는 Re > 4,000(대략). Re가 작으면 층류.","src":"기출 2025-32"},{"x":"상류: Fr > 1","o":"상류는 Fr < 1, Fr > 1은 사류.","src":"기출 2025-32"},{"x":"레이놀즈수로 알 수 있는 흐름은 사류, 상류, 한계류이다.","o":"레이놀즈수로 알 수 있는 흐름은 층류, 난류, 천이류이다.","src":"기출 2023-34"},{"x":"정상류: 일정 구간에서 흐름과 특성이 변하지 않는 흐름 (또는 시간에 따라 변하는 흐름)","o":"정상류는 모든 점에서 흐름과 특성이 시간에 따라 변하지 않는 흐름.","src":"기출 2026-31"}]},"#4":{"묶음":[{"머리":"손실의 분류","줄":[{"t":"주손실: 관 마찰손실(직선관에서 일어나는 마찰에 의한 손실).","src":"기출 2026-30"},{"t":"미소손실(부차적 손실): 유입, 유출, 급확대, 급축소, 점차확대, 밸브, 엘보 등 관 부속에서 생기는 손실. 마찰손실은 미소손실이 아니다.","src":"기출 2023-28"},{"t":"미소손실 일반식: h = K·V²/2g (K 손실계수).","src":"보충"}]},{"머리":"Darcy-Weisbach 식","줄":[{"t":"h_f = f·(L/D)·(V²/2g). 마찰손실수두는 관의 길이 L, 마찰손실계수 f, 유속의 제곱 V²에 비례하고 관경 D, 중력가속도 g에 반비례한다.","src":"기출 2024-28"},{"t":"유속의 제곱에 비례한다(반비례가 아님).","src":"기출 2023-33"},{"t":"층류의 마찰손실계수 f = 64/Re. 레이놀즈수만의 함수다.","src":"기출 2022-32"},{"t":"난류의 마찰손실계수는 레이놀즈수와 상대조도(e/D)의 함수다.","src":"기출 2022-32"},{"t":"유량으로 쓴 식: h_f = 8fLQ² ÷ (π²gD⁵). 지름 D는 5승에 반비례.","src":"기출 2021-28"},{"t":"관경 풀이 순서: 수면표고차 = 손실수두로 놓는다 → D⁵ = 8fLQ² ÷ (π²g·h) → 5제곱근. 문항에 f 조건 누락(정답은 약 633 mm).","src":"기출 2021-28"},{"t":"에너지선 경사 S = h_f/L = f·V²/(2gD). 층류면 f = 64/Re를 먼저 구한다. 예) D 10 cm, 0.5 L/s → V = 0.0637 m/s, 정답 2.08×10⁻⁴는 f ≈ 0.10(Re ≈ 640)일 때 나온다(문항에 동점성계수 조건 누락, 추정).","src":"기출 2025-31"},{"t":"예) 지름 2 mm 유리관, 0.25 cm³/s → V = Q ÷ A = 0.0796 m/s → Re = VD/ν → f = 64/Re ≈ 0.4 수준(ν 조건 누락).","src":"기출 2021-29"},{"t":"손실수두 유속 역산: 내경 200 mm, 3 m/s, 80 m, 정답 7.71 m는 f ≈ 0.042일 때 나온다(문항에 f 조건 누락, 추정).","src":"기출 2022-33"},{"t":"유량 역산: 내경 0.5 m, 400 m, 손실수두 10 m, 정답 0.517 m³/s는 f ≈ 0.035일 때 나온다(문항에 f 조건 누락, 추정). 순서는 V = √(h·2gD ÷ fL) → Q = AV.","src":"기출 2023-30"}]},{"머리":"층류 관 흐름(Hagen-Poiseuille)","줄":[{"t":"층류 손실수두 h = 128μLQ ÷ (πγD⁴). 유량이 일정하면 지름의 4승에 반비례한다.","src":"기출 2021-31"},{"t":"지름이 3배가 되면 손실수두는 1/3⁴ = 1/81배.","src":"기출 2021-31"},{"t":"층류 최대유속은 평균유속의 2배(관 중심).","src":"보충"}]},{"머리":"단면 급확대·급축소·유출 손실","줄":[{"t":"급확대 손실수두 h = K(V₁ − V₂)²/2g, 이론 K = 1.","src":"기출 2021-30"},{"t":"관이 큰 수조로 유입(V₂ ≈ 0)하면 h = V₁²/2g. 예) 지름 10 cm, 0.2 m³/s → V = 25.46 m/s → h = 648.4 ÷ 19.6 = 33.08 m.","src":"기출 2021-30"},{"t":"급축소·유입 손실은 입구 형상에 따라 K가 달라진다(둥근 입구 약 0.05, 돌출 입구 약 0.8).","src":"보충"}]},{"머리":"공동현상(캐비테이션)","줄":[{"t":"공동현상(cavitation): 펌프 내부에서 유속이 급변하거나 와류, 유로 장애 등으로 압력이 포화수증기압 근처 또는 이하로 낮아져 용존 기체가 분리되고 물이 기화하여 공동이 생기는 현상.","src":"기출 2023-32"},{"t":"공동현상 방지: 흡입수조의 형상과 치수를 과도한 편류·와류가 생기지 않게 한다.","src":"기출 2026-33"},{"t":"공동현상 방지: 계획토출량보다 현저히 벗어난 범위로 운전하는 것을 피한다.","src":"기출 2026-33"},{"t":"공동현상 방지: 펌프 설치 위치를 가능한 낮게 한다(흡입양정을 작게).","src":"기출 2026-33"},{"t":"방지(보충): 흡입관경을 크게, 흡입관 길이와 부속을 줄여 흡입손실을 줄인다. 유속과 회전수를 낮춘다. 양흡입 펌프 사용. 두 대 이상 직렬 운전 또는 흡입측 가압.","src":"보충"},{"t":"유효흡입수두 NPSHav가 필요흡입수두 NPSHre보다 커야 공동현상이 없다(NPSHav > NPSHre).","src":"보충"},{"t":"NPSHav = 대기압수두 − 포화증기압수두 − 흡입손실수두 − 흡입 실양정(수면이 펌프보다 낮을 때). 수면이 펌프보다 높으면 실양정을 더한다.","src":"보충"},{"t":"공동현상의 영향: 소음과 진동, 양정·효율 저하, 임펠러 침식(깃 손상).","src":"보충"}]}],"함정":[{"x":"관수로 흐름에서 미소손실에 해당하지 않는 것: 마찰손실이 미소손실에 해당한다.","o":"마찰손실은 주손실이고 미소손실에 해당하지 않는다.","src":"기출 2023-28"},{"x":"관수로 흐름의 손실 중 미소손실이 아닌 것은 급확대손실이다.","o":"급확대, 점차확대, 밸브 손실은 미소손실이고 관 마찰손실이 주손실이다.","src":"기출 2024-31"},{"x":"관수로 흐름에서 주손실에 해당하는 것은 유입손실, 유출손실, 밸브손실이다.","o":"주손실은 마찰손실이다.","src":"기출 2026-30"},{"x":"마찰손실수두는 유속의 제곱에 반비례한다.","o":"유속의 제곱에 비례한다.","src":"기출 2023-33"},{"x":"마찰손실수두는 관의 길이에 반비례한다.","o":"관의 길이에 비례한다.","src":"기출 2024-28"},{"x":"마찰손실수두는 마찰손실계수에 반비례한다.","o":"마찰손실계수에 비례한다.","src":"기출 2026-34"},{"x":"마찰손실수두는 유속의 제곱에 반비례한다(Darcy-Weisbach).","o":"비례한다.","src":"기출 2024-28"},{"x":"층류의 마찰손실계수는 레이놀즈수와 상대조도의 함수이다.","o":"층류의 f = 64/Re로 레이놀즈수만의 함수.","src":"기출 2022-32"},{"x":"층류의 마찰손실계수는 마하수와 코시수의 함수이다.","o":"레이놀즈수의 함수.","src":"기출 2022-32"},{"x":"층류의 마찰손실계수는 상대조도와 오일러수의 함수이다.","o":"레이놀즈수의 함수.","src":"기출 2022-32"},{"x":"공동현상을 피하기 위해 펌프의 설치 위치를 가능한 높게 한다.","o":"펌프 설치 위치를 낮게 하여 흡입양정을 줄인다.","src":"기출 2026-33"}]},"#5":{"묶음":[{"머리":"펌프의 분류","줄":[{"t":"터보형: 원심펌프(볼류트, 터빈), 사류펌프, 축류펌프. 임펠러 회전으로 속도에너지를 주고 압력으로 바꾼다.","src":"보충"},{"t":"용적형: 왕복펌프(피스톤, 플런저, 다이어프램)와 회전펌프(기어, 베인, 나사).","src":"보충"},{"t":"특수형: 와류펌프, 제트펌프, 기포펌프, 수격펌프 등.","src":"보충"},{"t":"원심펌프는 소유량·고양정에는 부적합하고, 양정은 임펠러 지름과 회전수가 클수록 커진다. 다단으로 양정을 높인다.","src":"보충"}]},{"머리":"회전펌프의 장단점","줄":[{"t":"회전펌프: 소용량, 고양정, 고점도 액체의 수송이 가능하다.","src":"기출 2022-34"},{"t":"회전펌프: 송출량의 맥동이 없고 구조가 간단하다.","src":"기출 2022-34"},{"t":"회전펌프는 회전수로 토출량을 조절한다. 행정으로 조절하는 것은 왕복펌프의 방식이다(회전펌프에는 행정이 없다).","src":"보충(추정)"}]},{"머리":"상사법칙","줄":[{"t":"상사법칙(회전수 N, 지름 D가 변할 때): 유량 Q ∝ N·D³, 전양정 H ∝ N²·D², 축동력 P ∝ N³·D⁵.","src":"기출 2024-32"},{"t":"지름이 같을 때: Q₂ = Q₁(N₂/N₁), H₂ = H₁(N₂/N₁)², P₂ = P₁(N₂/N₁)³.","src":"기출 2024-32"},{"t":"유량은 회전수 비에 비례, 전양정은 회전수 비의 제곱에 비례, 축동력은 회전수 비의 3승에 비례한다.","src":"기출 2024-32"},{"t":"회전수가 2배면 Q 2배, H 4배, P 8배.","src":"보충"}]},{"머리":"비속도","줄":[{"t":"비속도 N_s = N·√Q ÷ H^(3/4). N은 회전수(rpm), Q는 유량(m³/min), H는 양정(m). 각속도 ω가 아니라 회전수 N을 쓴다.","src":"기출 2025-33"},{"t":"다단펌프의 비속도는 1단 양정(H/단수)으로 계산한다.","src":"보충"},{"t":"비속도가 작으면 고양정·소유량(원심), 크면 저양정·대유량(축류) 쪽이다.","src":"보충"}]},{"머리":"펌프 동력 계산","줄":[{"t":"수동력 P_w = γ·Q·H = 9.8·Q·H (kW, Q m³/s, H m).","src":"기출 2024-33"},{"t":"축동력 P = γQH ÷ η. 전동기 동력 = 축동력 × 전달계수 K.","src":"기출 2024-33"},{"t":"H는 압력수두와 속도수두 등을 합한다. 예) 2.2 kgf/cm² = 22 m, 지름 0.5 m 관 유속 5.09 m/s → 속도수두 1.32 m. Q 1 m³/s, 합계 23.3 m → 수동력 228.7 kW. 정답 268.9 kW는 효율 85%를 적용한 값(추정).","src":"기출 2024-33"},{"t":"마력 환산: 1 HP = 0.746 kW, 1 PS = 0.735 kW.","src":"기출 2026-32"},{"t":"양수 동력 풀이 순서: 실양정(20 m) + 관 마찰손실 + 속도수두 = 전양정 → P = γQH(kW) → HP로 환산. 예) 실양정만으로는 98 kW(약 131 HP). 정답 약 170 HP는 손실수두를 더한 값(문항에 손실 조건 누락).","src":"기출 2026-32"},{"t":"직렬 운전은 유량 같고 양정이 합해지며, 병렬 운전은 양정 같고 유량이 합해진다.","src":"보충"}]},{"머리":"서징(맥동 현상)","줄":[{"t":"서징(surging): 펌프 운전 중 압력과 유량이 주기적으로 변동하는 현상. H-Q 곡선이 우상향(산형) 구간에서 운전할 때 일어난다.","src":"보충"},{"t":"방지: H-Q 곡선이 우하향 구배 특성을 갖는 펌프를 사용한다.","src":"기출 2025-34"},{"t":"방지: 배관 안에 수조 또는 기체 상태인 부분이 존재하지 않도록 한다.","src":"기출 2025-34"},{"t":"방지: 바이패스관을 사용하여 운전점이 H-Q 곡선의 우하향 구배 범위 안에 있도록 한다.","src":"기출 2025-34"},{"t":"방지: 유량조절밸브는 흡입측이 아니라 펌프 토출측(펌프에 가까이)에 설치한다.","src":"보충"},{"t":"방지(보충): 회전수 변경, 임펠러 지름 조정, 풍량·유량 정격 범위 유지.","src":"보충"}]},{"머리":"수격작용","줄":[{"t":"수격작용: 관 안 유체의 속도가 급변하여 압력이 급상승·하강하는 현상.","src":"보충"},{"t":"방지: 관경을 크게 하여 유속을 줄인다. 플라이휠, 에어챔버, 서지탱크, 완폐식 체크밸브를 설치한다.","src":"보충"}]}],"함정":[{"x":"회전펌프: 행정의 조절로 토출량을 조절할 수 있다.","o":"출제 오답(바른 조절 방식은 회전수 조절, 행정 조절은 왕복펌프)","src":"기출 2022-34"},{"x":"펌프의 축동력은 회전수 비의 4승에 비례한다.","o":"회전수 비의 3승에 비례한다.","src":"기출 2024-32"},{"x":"비속도: ω×√Q / H^(3/4)","o":"N×√Q / H^(3/4) (N은 회전수).","src":"기출 2025-33"},{"x":"비속도: ω×√Q / H^(3/2) 또는 N×√Q / H^(3/2)","o":"분모는 H^(3/4).","src":"기출 2025-33"},{"x":"서징 방지: 유량조절 밸브를 흡입측에 최대한 가까이 설치·조절한다.","o":"유량조절밸브는 토출측에 두고, 펌프 H-Q 곡선은 우하향 구배를 사용한다.","src":"기출 2025-34"}]},"#6":{"묶음":[{"머리":"물의 열량 상수","줄":[{"t":"물의 비열 1 cal/g·℃ = 1 kcal/kg·℃ = 4.18 kJ/kg·K.","src":"기출 2024-40"},{"t":"물의 융해열(얼음 → 물) 약 79.7 cal/g(약 80 kcal/kg).","src":"기출 2022-40"},{"t":"물의 증발잠열(100℃) 약 539 cal/g = 539 kcal/kg = 2,253 kJ/kg.","src":"기출 2024-40"},{"t":"얼음 0℃ → 100℃ 수증기: 79.7 + 100 + 539 = 약 719 cal/g.","src":"기출 2025-36"},{"t":"20℃ 물 1 g → 100℃ 수증기: 80 + 539.6 = 약 619.6 cal.","src":"기출 2023-41"},{"t":"15℃ 물 1 kg → 100℃ 수증기: 현열 85 kcal(355.3 kJ) + 증발잠열 539 kcal(2,253 kJ) = 약 624 kcal. 이 과정에는 용융잠열이 없다.","src":"기출 2024-40"},{"t":"냉각효과 계산 순서: 현열(m·c·ΔT) → 증발잠열(m·r)을 더한다. 얼음이면 융해열을 먼저 더한다.","src":"기출 2024-40"}]},{"머리":"물의 팽창","줄":[{"t":"물 → 수증기 팽창: 1 g 물(1 cm³)이 수증기가 되면 이상기체식으로 V = (1/18)·22.4·(T/273) L.","src":"기출 2024-38"},{"t":"4℃ 물 → 200℃(473 K) 수증기: (22.4/18)×(473/273) = 2.156 L = 2,156 cm³ → 약 2,156배.","src":"기출 2024-38"},{"t":"100℃ 수증기는 약 1,700배 팽창한다(물 1 L → 약 1,700 L).","src":"기출 2024-38"}]},{"머리":"비열 비교","줄":[{"t":"상온·표준상태에서 물의 비열은 1 cal/g·℃로 소화약제 후보 중 가장 크다. 사염화탄소 약 0.2, 파라핀 약 0.5~0.7, 가스계 약제는 훨씬 작다.","src":"기출 2026-36"},{"t":"얼음 비열 약 0.5 cal/g·℃, 수증기 비열 약 0.47 cal/g·℃.","src":"보충"}]},{"머리":"연소반응 계산","줄":[{"t":"연소는 발열반응이다. 탄소의 1차 연소(C → CO)와 2차 연소(CO → CO₂)는 모두 발열반응.","src":"기출 2026-35"},{"t":"메탄 연소: CH₄ + 2O₂ → CO₂ + 2H₂O.","src":"기출 2021-41"},{"t":"공기 중 산소 21 vol%, 질소 79 vol%. 산소 1 mol에 동반하는 질소 = 79/21 = 3.76 mol.","src":"기출 2021-41"},{"t":"생성물 부피비 풀이 순서: 필요 산소 mol → 동반 N₂ mol → 생성물 합계(N₂ 포함) → N₂ ÷ 합계. 예) 메탄 1 mol: O₂ 2 mol, N₂ 7.52 mol, 생성물 CO₂ 1 + H₂O 2 + N₂ 7.52 = 10.52 mol → N₂ 71.5%.","src":"기출 2021-41"},{"t":"탄소 완전연소: C + O₂ → CO₂(발열, 약 94 kcal/mol).","src":"보충"},{"t":"산소 농도 21 vol%, 소화에 필요한 산소 한계농도는 약 15%(CO₂ 방출 시 약 28.6% 이상 CO₂ 필요).","src":"보충"}]}],"함정":[{"x":"물 1 kg 당 흡수한 용융잠열은 약 80 kcal이다.","o":"15℃ 물이 수증기가 되는 과정에는 용융잠열이 포함되지 않는다(용융잠열은 얼음이 물로 될 때).","src":"기출 2024-40"},{"x":"탄소의 연소반응 ㄱ·ㄴ은 흡열반응이다.","o":"두 반응(C → CO, CO → CO₂) 모두 발열반응이다.","src":"기출 2026-35"},{"x":"비열이 가장 큰 물질은 HFC-23, 사염화탄소, 파라핀이다.","o":"물이 가장 크다(1 cal/g·℃).","src":"기출 2026-36"}]},"#7":{"묶음":[{"머리":"물의 성질","줄":[{"t":"물은 극성분자이며 분자 사이에 수소결합을 한다.","src":"기출 2023-41"},{"t":"물의 융해잠열 약 79.7 cal/g. 20℃ 물 1 g을 100℃ 수증기로 만드는 데 약 619.6 cal.","src":"기출 2023-41"},{"t":"물의 임계온도 약 374℃. 임계온도 이상에서는 압력을 가해도 액화되지 않는다.","src":"기출 2023-41"},{"t":"물의 소화효과: 냉각(주), 질식(수증기 팽창), 유화·희석(수용성 액체). 무상 방사로 전기화재·유류화재에 활용한다.","src":"보충"}]},{"머리":"화재 종류와 약제 적응성","줄":[{"t":"A급(일반), B급(유류), C급(전기), D급(금속), K급(주방·식용유).","src":"보충"},{"t":"A급 화재에 수성막포를 사용하면 질식 효과로 소화할 수 있다.","src":"기출 2022-35"},{"t":"B급 화재에 물은 부적합하다(봉상 주수 시 유류 확산). 냉각이 주된 효과이며 부촉매 효과가 아니다.","src":"기출 2022-35"},{"t":"C급 화재에 ABC급 분말을 사용하면 부촉매 효과로 소화할 수 있다.","src":"기출 2022-35"},{"t":"K급 화재에 강화액을 사용하면 냉각 효과로 소화할 수 있다.","src":"기출 2022-35"}]},{"머리":"강화액 소화약제","줄":[{"t":"강화액소화약제: 알칼리 금속염류 등을 주성분으로 하는 수용액으로 알칼리성 반응을 나타내야 한다.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제6조"},{"t":"강화액의 응고점은 -20 ℃ 이하.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제6조"},{"t":"강화액의 표면장력은 33 mN/m 이하(K급 화재용 포함 약제는 적용하지 않음). 비중은 설계값 ±0.02, pH는 6~9(설계값 ±0.4).","src":"소화약제의 형식승인 및 제품검사의 기술기준 제6조"},{"t":"침전량은 0.1 vol% 이하, 변질시험 후 0.2 vol% 이하.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제6조"},{"t":"강화액은 전기화재에 무상으로 방사하는 경우 사용할 수 있다.","src":"기출 2021-39"},{"t":"강화액의 소화효과는 냉각과 알칼리금속염(칼륨염)의 부촉매(억제) 작용이다. 화염과 접촉하면 질소가 발생하여 질식소화한다는 설명은 맞지 않다.","src":"보충"},{"t":"금속화재에는 강화액(수계 약제)을 쓸 수 없다.","src":"기출 2021-35"}]},{"머리":"K급 소화약제","줄":[{"t":"K급 소화약제의 주성분: 탄산칼륨(K₂CO₃) 또는 초산칼륨(CH₃COOK) 등.","src":"기출 2025-37"},{"t":"식용유화재에서 비누화반응으로 산소를 차단하고 재발화를 방지한다.","src":"기출 2025-37"},{"t":"일반 ABC분말소화기보다 냉각효과가 뛰어나다.","src":"기출 2025-37"},{"t":"K급 소화약제는 주방(식용유)화재용이며 A·B·C급에 두루 적응성이 좋은 약제가 아니다. 가연성 금속화재에도 적응성이 없다.","src":"기출 2025-37"}]},{"머리":"포소화약제 종류와 성질","줄":[{"t":"포소화약제: 주원료에 포 안정제 등을 첨가한 액상으로 물과 일정 농도로 혼합한 뒤 공기를 기계적으로 혼입시켜 거품을 만들어 소화한다.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제2조"},{"t":"종류: 단백포(단백질 가수분해물), 합성계면활성제포, 수성막포(합성계면활성제 중 기름 표면에 수성막을 형성), 알코올형포(수용성 용제 소화용).","src":"소화약제의 형식승인 및 제품검사의 기술기준 제2조"},{"t":"수성막포: 탄화불소계 계면활성제를 주성분으로 물의 표면장력을 낮추어 기름 표면에 수성막을 만든다.","src":"기출 2026-37"},{"t":"수성막포의 수성막 성능은 확산계수로 나타낸다. 확산계수 3.5 이상(20±2 ℃, 사이클로헥세인).","src":"소화약제의 형식승인 및 제품검사의 기술기준 제4조"},{"t":"수성막포는 20 ℃의 사이클로헥세인 액면 위에 수성막을 형성할 수 있어야 한다.","src":"기출 2026-37"},{"t":"기출 2026-37에서 수성막포와 제3종 분말소화약제를 함께 쓰면 소화효율을 높일 수 있다는 선지는 옳은 선지로 출제됐다.","src":"기출 2026-37"},{"t":"알코올형포: 수용성용제(알코올류, 에테르류, 에스테르류, 케톤류, 알데히드류, 아민류, 니트릴류, 유기산 등) 소화용.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제2조"},{"t":"저발포용: 표준발포노즐로 팽창비 6배(수성막포 5배) 이상. 고발포용: 500배 이상.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제2조"}]},{"머리":"포소화약제 형식승인 기준","줄":[{"t":"유동점: 사용하한온도보다 2.5 ℃ 이하.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제4조"},{"t":"수소이온농도 pH 6~9, 설계값 ±0.4 이내(2023 기출 당시 수성막포 6.0 이상 8.5 이하를 옳은 선지로 출제).","src":"소화약제의 형식승인 및 제품검사의 기술기준 제4조"},{"t":"알코올형포의 비중 0.90 이상 1.20 이하는 2023 기출에서 옳은 선지로 출제(현행 비중표는 이미지 표라 원문 텍스트 미확인).","src":"기출 2023-39"},{"t":"비중은 (20±0.5) ℃에서 설계값 ±0.02 이내. 사용온도는 5 ℃ 단위로 구분.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제4조"},{"t":"점도는 설계값 ±30 % 이내이고 200 ㎟/s 이하(단백포 400, 알코올형 3,500 ㎟/s 이하).","src":"소화약제의 형식승인 및 제품검사의 기술기준 제4조"},{"t":"침전량 0.1 vol% 이하(원심분리), 인화점 60 ℃ 이상.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제4조"},{"t":"변질시험: 65±2 ℃에서 216시간 보존 후 실온 환원, 다시 -18±2 ℃에서 24시간 보존 후 실온 환원.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제2조"},{"t":"저발포용: 표준발포노즐(수압 0.7 MPa, 10 L/min)에서 팽창율 6배(수성막 5배) 이상, 25 % 환원시간 1분 이상.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제4조"},{"t":"고발포용: 수압 0.1 MPa, 6 L/min, 풍량 13 ㎥/min에서 팽창율 500배 이상, 25 % 환원시간 3분 이상.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제4조"},{"t":"방수포용: 팽창율 6배(수성막 5배) 이상 10배 미만, 25 % 환원시간 2분 이상.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제4조"}]},{"머리":"발포배율과 환원시간","줄":[{"t":"발포배율(팽창비) = 발생한 포의 부피 ÷ 포수용액의 부피.","src":"기출 2023-38"},{"t":"포수용액 부피 = 원액 ÷ 농도. 예) 원액 12 L, 3 % → 수용액 400 L = 0.4 m³. 포 4 m³ → 4 ÷ 0.4 = 10배.","src":"기출 2023-38"},{"t":"환원시간: 발포 전 포수용액 용량의 25 %가 거품에서 환원되는 데 걸리는 시간.","src":"기출 2021-36"},{"t":"환원시간이 길수록 양호한 포소화약제다.","src":"기출 2021-36"},{"t":"발포배율이 커지면 포 막이 얇아져 환원시간이 짧아진다. 포의 막이 두꺼울수록 환원시간은 길어진다.","src":"기출 2021-36"},{"t":"발포배율이 작은 포는 포의 직경이 작고 막이 두껍다.","src":"기출 2021-36"}]},{"머리":"포 혼합장치 방식","줄":[{"t":"라인 푸로포셔너: 펌프와 발포기 중간에 설치된 벤추리관의 벤추리작용으로 포소화약제를 흡입·혼합한다.","src":"기출 2022-39"},{"t":"펌프 푸로포셔너: 펌프 토출관과 흡입관 사이에 바이패스관을 두고 그 사이에 혼합기를 설치해 약제를 흡입·혼합한다.","src":"보충"},{"t":"프레져 푸로포셔너: 펌프와 발포기 중간에 설치된 벤추리관 부분의 차압과 가압수로 약제 탱크 안의 약제를 혼합한다(탱크 내 격막 사용).","src":"보충"},{"t":"프레져사이드 푸로포셔너: 펌프 토출측 배관에 압입기를 설치하여 약제를 압입한다.","src":"보충"},{"t":"압축공기포 믹싱챔버방식: 압축공기 또는 압축질소를 일정 비율로 섞어 포를 만든다.","src":"보충"}]}],"함정":[{"x":"환원시간이 짧을수록 양호한 포소화약제이다.","o":"환원시간이 길수록 양호한 포소화약제다.","src":"기출 2021-36"},{"x":"강화액 소화약제의 용액은 약산성이다.","o":"강화액은 알칼리성 반응을 나타내는 수용액.","src":"기출 2021-39"},{"x":"강화액은 화염과 접촉 시 열분해에 의하여 질소가 발생하여 질식소화 한다.","o":"강화액의 소화효과는 냉각과 부촉매 작용.","src":"기출 2021-39"},{"x":"강화액은 전기화재 시 무상방사 하는 경우라도 소화약제로 사용할 수 없다.","o":"무상방사 하는 경우 전기화재에 사용할 수 있다.","src":"기출 2021-39"},{"x":"B 급 화재의 경우 물을 사용하여 부촉매 효과로 소화할 수 있다.","o":"물은 B급 화재에 적합하지 않다. 물의 주된 효과는 냉각이다.","src":"기출 2022-35"},{"x":"고발포용포소화약제는 거품의 팽창율은 500배 이상이어야 하며, 발포전 포수용액 용량의 25%인 포수용액이 거품으로부터 환원되는데 필요한 시간이 1분 이하이어야 한다.","o":"환원시간은 3분 이상이어야 한다.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제4조"},{"x":"소화약제인 물: 물의 임계온도 이상에서는 압력을 조금만 가해도 쉽게 액화된다.","o":"임계온도 이상에서는 압력을 가해도 액화되지 않는다.","src":"기출 2023-41"},{"x":"K급 소화약제는 A급, B급, C급 화재에도 적응성이 좋다.","o":"K급 소화약제는 주방(식용유)화재용이다.","src":"기출 2025-37"},{"x":"수성막포소화약제는 탄화불소계 계면활성제를 주성분으로 물의 표면장력을 높이는 효과로 사용한다.","o":"물의 표면장력을 낮추는 효과로 사용한다.","src":"기출 2026-37"}]},"#8":{"묶음":[{"머리":"분말소화약제 종류","줄":[{"t":"제1종 분말: 탄산수소나트륨(NaHCO₃, 중탄산나트륨)을 주성분으로 한 분말소화약제.","src":"분말소화설비의 화재안전기술기준(NFTC 108) 1.7.1.12"},{"t":"제2종 분말: 탄산수소칼륨(KHCO₃)을 주성분으로 한 분말소화약제.","src":"분말소화설비의 화재안전기술기준(NFTC 108) 1.7.1.13"},{"t":"제3종 분말: 인산염을 주성분으로 한 분말소화약제(제1인산암모늄 NH₄H₂PO₄).","src":"분말소화설비의 화재안전기술기준(NFTC 108) 1.7.1.14"},{"t":"제4종 분말: 탄산수소칼륨과 요소가 화합된 분말소화약제.","src":"분말소화설비의 화재안전기술기준(NFTC 108) 1.7.1.15"},{"t":"적응 화재: 제1종·제2종·제4종은 B·C급, 제3종은 A·B·C급.","src":"보충"},{"t":"설치 대상 약제: 분말소화설비는 제1종~제4종 분말을 쓰되, 차고 또는 주차장에 설치하는 분말소화설비의 소화약제는 제3종 분말로 해야 한다.","src":"분말소화설비의 화재안전기술기준(NFTC 108) 2.3.1"},{"t":"착색: 칼륨의 중탄산염이 주성분인 약제는 담회색, 인산염 등이 주성분인 약제는 담홍색 또는 황색으로 착색하고 서로 혼합하지 않는다. 제1종은 백색.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제7조"},{"t":"제4종 분말은 회색(보충), 제2종 분말은 담회색(자색 계열로 부르던 교재도 있음).","src":"보충"}]},{"머리":"열분해 반응","줄":[{"t":"제1종: 2NaHCO₃ → Na₂CO₃ + CO₂ + H₂O (약 270 ℃ 이상에서 분해, 흡열).","src":"보충"},{"t":"제2종: 2KHCO₃ → K₂CO₃ + CO₂ + H₂O (약 190 ℃에서 분해, 흡열).","src":"보충"},{"t":"제3종: NH₄H₂PO₄ → NH₃ + H₃PO₄(오르토인산, 약 190 ℃) → H₄P₂O₇(피로인산, 약 215 ℃) → HPO₃(메타인산, 약 300 ℃).","src":"보충"},{"t":"제4종: 2KHCO₃ + (NH₂)₂CO → K₂CO₃ + 2NH₃ + 2CO₂.","src":"보충"},{"t":"제3종 분말의 열분해 생성물 중 섬유소의 탈수·탄화작용을 하는 것은 오르토인산(H₃PO₄)이다.","src":"기출 2025-40"},{"t":"메타인산(HPO₃)은 숯 표면에 유리상 피막을 만들어 산소를 차단하는 방진효과가 있다.","src":"기출 2024-39"}]},{"머리":"제3종 분말의 소화효과","줄":[{"t":"소화효과(6가지): 열분해 시 흡열반응에 의한 냉각, 불연성가스(NH₃, H₂O)에 의한 질식, 메타인산의 방진, 오르토인산의 섬유소 탈수·탄화, 분말 운무에 의한 열방사 차단, 유리된 NH₄⁺에 의한 부촉매.","src":"기출 2024-39"},{"t":"제3종 분말이 다른 분말과 달리 A급 화재에 적용되는 이유: 메타인산의 방진효과(ㄷ)와 오르토인산에 의한 섬유소의 탈수·탄화작용(ㄹ). 냉각·질식·열방사 차단·부촉매는 다른 분말에도 공통이다.","src":"기출 2024-39"}]},{"머리":"분말소화약제 형식승인 기준","줄":[{"t":"성분비: 중탄산나트륨 약제는 NaHCO₃ 90 wt% 이상, 중탄산칼륨 약제는 KHCO₃ 90 wt% 이상, 인산염류 등 약제는 제1인산암모늄 등 함량 75 wt% 이상(설계값 -5 %~+15 %).","src":"소화약제의 형식승인 및 제품검사의 기술기준 제7조"},{"t":"수분함유율 0.2 wt% 이하. 흡습율: 중탄산나트륨 약제 0.2 wt%, 중탄산칼륨 약제 2 wt%, 인산염류 등 약제 1.5 wt% 이하.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제7조"},{"t":"겉보기비중 0.8 g/mL 이상(설계값 ±0.1). 분말을 수면에 살포하면 1시간 이내에 침강하지 않아야 한다.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제7조"},{"t":"침입도시험기(penetrometer)로 시험하여 15 mm 이상 침투되어야 한다(2023 기출은 10 mm 이하를 틀린 선지로 출제).","src":"소화약제의 형식승인 및 제품검사의 기술기준 제7조"},{"t":"온도상승시험: 60±2 ℃에서 7일 보존, 실온 3일 보존 후 유동성이 있고 고화되지 않아야 한다. C급 화재용은 5,000 V 교류 절연내력시험.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제7조"},{"t":"분말은 방습가공을 한 나트륨 또는 칼륨의 중탄산염, 인산염류, 황산염류 등 방염성 염류로서 형식승인 기준에 적합해야 한다.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제7조"}]},{"머리":"분말소화설비 저장용기·가압가스","줄":[{"t":"저장용기 설치장소: 방호구역 외(방호구역 내라면 피난구 부근), 온도 40 ℃ 이하이고 온도변화가 작은 곳, 직사광선·빗물 침투 우려가 없는 곳, 방화문으로 방화구획 된 실, 용기 간 간격 3 ㎝ 이상.","src":"분말소화설비의 화재안전기술기준(NFTC 108) 2.1.1"},{"t":"저장용기의 충전비는 0.8 이상으로 한다(제1종~제4종 모두).","src":"분말소화설비의 화재안전기술기준(NFTC 108) 2.1.2.4"},{"t":"저장용기 내용적(1 kg당): 제1종 0.8 L, 제2종 1.0 L, 제3종 1.0 L, 제4종 1.25 L(표는 원문 이미지로 텍스트 미확인, 기출 선지와 일치).","src":"보충"},{"t":"안전밸브: 가압식은 최고사용압력의 1.8배 이하, 축압식은 용기 내압시험압력의 0.8배 이하에서 작동(2022 기출 당시 가압식 2.5배를 틀린 선지로 출제).","src":"분말소화설비의 화재안전기술기준(NFTC 108) 2.1.2.2"},{"t":"저장용기에는 정압작동장치, 잔류 약제 청소장치를 설치하고, 축압식에는 사용압력 범위를 표시한 지시압력계를 설치한다.","src":"분말소화설비의 화재안전기술기준(NFTC 108) 2.1.2"},{"t":"가압용·축압용 가스는 질소가스 또는 이산화탄소로 한다.","src":"분말소화설비의 화재안전기술기준(NFTC 108) 2.2.4.1"},{"t":"가압용 질소: 소화약제 1 ㎏마다 40 L(35 ℃, 1기압 환산) 이상. 축압용 질소: 1 ㎏마다 10 L 이상. 이산화탄소: 소화약제 1 ㎏에 20 g에 배관 청소에 필요한 양을 가산한 양 이상.","src":"분말소화설비의 화재안전기술기준(NFTC 108) 2.2.4.2~2.2.4.3"},{"t":"가압용가스용기를 3병 이상 설치한 경우 2개 이상의 용기에 전자개방밸브를 부착한다. 압력조정기는 2.5 ㎫ 이하에서 조정 가능한 것.","src":"분말소화설비의 화재안전기술기준(NFTC 108) 2.2.2~2.2.3"},{"t":"분사헤드: 전역방출·국소방출 모두 저장량을 30초 이내에 방출. 호스릴은 수평거리 15 m 이하.","src":"분말소화설비의 화재안전기술기준(NFTC 108) 2.8"},{"t":"국소방출방식 저장량은 계산식 산출량에 1.1을 곱한 양 이상.","src":"분말소화설비의 화재안전기술기준(NFTC 108) 2.3.2.2"},{"t":"축압식 분말소화기의 충압가스: 질소, 헬륨, 이산화탄소는 기출 선지로 옳게 출제, 일산화탄소는 충압가스가 아니다.","src":"기출 2025-42"}]},{"머리":"분말소화약제 약제량 계산","줄":[{"t":"전역방출: 방호구역 체적 1 ㎥당 약제량(종별 표) + 자동폐쇄장치가 없는 개구부는 면적당 가산량. 표는 원문 이미지로 텍스트 미확인.","src":"분말소화설비의 화재안전기술기준(NFTC 108) 2.3.2.1"},{"t":"통상 암기값(보충, 표 텍스트 미확인): 체적 1 ㎥당 제1종 0.60 kg, 제2종·제3종 0.36 kg, 제4종 0.24 kg. 개구부 1 ㎡당 제1종 4.5 kg, 제2종·제3종 2.7 kg, 제4종 1.8 kg.","src":"보충"}]},{"머리":"금속화재(D급)","줄":[{"t":"금속화재: 가연성금속에 의한 화재. 금속이 괴상이 아니라 고운 분말이나 가는 선 형태로 존재하면 위험성이 더 커진다.","src":"기출 2021-35"},{"t":"Na, K 등은 물과 만나면 수소가스를 발생시키는 금수성 물질이다. 리튬·나트륨에 수계 소화약제를 쓰면 폭발성이 강한 수소를 발생시킨다.","src":"기출 2025-35"},{"t":"금속화재 대상 금속: 알루미늄, 마그네슘, 아연 등의 금속 또는 금속분말.","src":"기출 2026-41"},{"t":"팽창질석을 사용하여 금속화재 표면을 덮어 질식소화할 수 있다.","src":"기출 2026-41"},{"t":"D급 소화약제: 염화나트륨, 흑연, 구리 등을 주성분으로 하는 분말 또는 과립 형태의 혼합물.","src":"기출 2025-35"},{"t":"Met-L-X: 염화나트륨 주제에 고분자물질을 혼합한 소화약제로 나트륨 및 칼륨 화재에 적응성이 있다.","src":"기출 2025-35"},{"t":"금속화재의 주된 소화약제는 건조사(마른모래), 팽창질석·팽창진주암, D급 분말 등이다. 이산화탄소·강화액·K급 약제는 적응성이 없다.","src":"기출 2026-41"}]},{"머리":"고체에어로졸소화설비","줄":[{"t":"고체에어로졸소화설비: 설계밀도 이상의 고체에어로졸을 방호구역 전체에 균일하게 방출하는 설비로서 분산(Dispersed)방식이 아닌 압축(Condensed)방식.","src":"고체에어로졸소화설비의 화재안전성능기준(NFPC 110) 제3조제1호"},{"t":"고체에어로졸화합물: 과산화물질, 가연성물질 등의 혼합물로서 화재를 소화하는 비전도성의 미세입자인 에어로졸을 만드는 고체화합물.","src":"고체에어로졸소화설비의 화재안전성능기준(NFPC 110) 제3조제2호"},{"t":"고체에어로졸: 고체에어로졸화합물의 연소과정으로 생성된 직경 10 마이크로미터 이하의 고체 입자와 기체 상태 물질의 혼합물.","src":"고체에어로졸소화설비의 화재안전성능기준(NFPC 110) 제3조제3호"},{"t":"소화밀도: 방호공간 내 규정된 시험조건의 화재를 소화하는 데 필요한 단위체적(㎥)당 고체에어로졸화합물의 질량(g). 설계밀도 = 소화밀도 × 안전계수.","src":"고체에어로졸소화설비의 화재안전성능기준(NFPC 110) 제3조제5~6호"},{"t":"일반조건: 전기 전도성이 없을 것. 약제 방출 후 재발화 방지를 위해 최소 10분간 소화밀도를 유지할 것. 비상주장소에 한하여 설치할 것. 방호구역의 밀폐성을 확보할 것.","src":"고체에어로졸소화설비의 화재안전성능기준(NFPC 110) 제4조"},{"t":"설치제외: 산화성 물질, 자기반응성 금속, 금속 수소화물, 자동 열분해를 하는 화학물질 등을 포함한 화재와 폭발성 물질이 존재할 가능성이 있는 장소.","src":"고체에어로졸소화설비의 화재안전성능기준(NFPC 110) 제5조"},{"t":"고체에어로졸발생기: 천장이나 벽면 상부에 설치, 하나의 방호구역에는 동일 제품군·동일 크기를 설치, 방호구역 높이는 형식승인 받은 최대 설치높이 이하, 인체·가연물과 최소 열 안전이격거리 준수.","src":"고체에어로졸소화설비의 화재안전성능기준(NFPC 110) 제6조"},{"t":"기동 시 1분 이내에 설계밀도의 95 % 이상을 방호구역에 균일하게 방출한다. 방출 개시 후 1분 이상 경보를 계속한다.","src":"고체에어로졸소화설비의 화재안전성능기준(NFPC 110) 제8조, 제10조"},{"t":"수동식 기동장치는 제어반마다 설치하고, 방출지연스위치를 설치한다. 오작동 제어를 위해 제어반 인근에 설비정지스위치를 설치한다.","src":"고체에어로졸소화설비의 화재안전성능기준(NFPC 110) 제8조, 제9조"},{"t":"음향장치: 방호구역의 각 부분에서 하나의 음향장치까지 수평거리 25 m 이하, 1 m 거리에서 90 dB 이상, 정격전압 80 %에서 음을 발할 것.","src":"고체에어로졸소화설비의 화재안전성능기준(NFPC 110) 제10조"},{"t":"화재감지기: 광전식 공기흡입형 감지기, 아날로그 방식의 광전식 스포트형 감지기 또는 적응성이 있다고 인정된 감지기.","src":"고체에어로졸소화설비의 화재안전성능기준(NFPC 110) 제11조"},{"t":"방호구역은 설비 기동 시 자동으로 폐쇄되어야 한다. 비상전원은 최소 20분 이상 유효하게 공급. 과압배출구를 설치한다.","src":"고체에어로졸소화설비의 화재안전성능기준(NFPC 110) 제12조, 제13조, 제15조"}]}],"함정":[{"x":"소화 시 강화액 소화약제를 사용한다(금속화재).","o":"금속화재에는 수계 약제인 강화액을 쓸 수 없다. 마른모래, 팽창질석, D급 분말을 쓴다.","src":"기출 2021-35"},{"x":"제2종 분말 소화약제 1 kg 당 저장용기의 내용적은 1.25 ℓ로 하고 저장용기의 충전비는 0.8이상으로 할 것.","o":"제2종 분말은 1 kg당 1.0 L, 1.25 L는 제4종.","src":"기출 2022-42"},{"x":"제3종 분말 소화약제 1 kg 당 저장용기의 내용적은 1 ℓ로 하고 저장용기의 충전비는 1.1이상으로 할 것.","o":"충전비는 0.8 이상.","src":"기출 2022-42"},{"x":"저장용기에는 가압식은 최고사용압력의 2.5 배 이하, 축압식은 용기의 내압시험압력의 0.8 배 이하의 압력에서 작동하는 안전밸브를 설치할 것.","o":"가압식은 최고사용압력의 1.8배 이하.","src":"분말소화설비의 화재안전기술기준(NFTC 108) 2.1.2.2"},{"x":"제1종 분말의 주성분은 KHCO3이다.","o":"제1종 분말의 주성분은 NaHCO₃(탄산수소나트륨).","src":"기출 2023-42"},{"x":"칼륨의 중탄산염이 주성분인 소화약제는 황색, 인산염이 주성분인 소화약제는 담홍색으로 각각 착색하여야 한다.","o":"칼륨의 중탄산염 약제는 담회색, 인산염 약제는 담홍색 또는 황색.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제7조"},{"x":"분말상태의 소화약제는 페네트로메타(penetrometer)시험기로 시험한 경우 10 mm 이하 침투되어야 한다.","o":"15 mm 이상 침투되어야 한다.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제7조"},{"x":"K급 소화약제는 가연성 금속화재에 적응성이 좋다.","o":"K급 소화약제는 식용유(주방)화재용이며 금속화재에는 쓰지 않는다.","src":"기출 2025-35"},{"x":"금속화재의 주된 소화약제는 이산화탄소 소화약제이다.","o":"이산화탄소는 금속화재에 쓸 수 없다. 금속화재는 건조사, 팽창질석, D급 분말 등.","src":"기출 2026-41"},{"x":"“고체에어로졸소화설비”란 설계밀도 이상의 고체에어로졸을 방호구역 전체에 균일하게 방출하는 설비로서 분산(Dispersed)방식을 말한다.","o":"분산방식이 아니라 압축(Condensed)방식.","src":"고체에어로졸소화설비의 화재안전성능기준(NFPC 110) 제3조제1호"}]},"#9":{"묶음":[{"머리":"이산화탄소의 성질","줄":[{"t":"이산화탄소: 불연성 가스, 무색·무취, 공기에 대한 비중 약 1.5(44/29).","src":"기출 2025-41"},{"t":"약제 방출 시 인체에 동상과 질식의 우려가 있다.","src":"기출 2025-41"},{"t":"전기 절연성이 우수하여 전기화재에 적응성이 있다.","src":"기출 2025-41"},{"t":"금속분화재에는 사용할 수 없다(금속이 이산화탄소와 반응). 소화효과는 질식·냉각이다.","src":"기출 2025-41"},{"t":"상태 변화: 삼중점 -56.7 ℃(5.2 atm), 임계온도 31.1 ℃, 승화점 -78.5 ℃.","src":"보충"},{"t":"몰 계산: 표준상태(0 ℃, 1기압) 기체 1 mol = 22.4 L, 이산화탄소 분자량 44. 예) 44.8 ㎥ = 2,000 mol × 44 g = 88 kg.","src":"기출 2025-38"}]},{"머리":"농도 계산","줄":[{"t":"이산화탄소 농도(%) = (21 − 한계산소농도) ÷ 21 × 100 (무유출 방식).","src":"기출 2026-40"},{"t":"예) 산소를 10 vol%로 낮추려면 (21 − 10) ÷ 21 × 100 = 52.38 vol%.","src":"기출 2026-40"},{"t":"설계농도 = 최소소화농도 × 안전율(약 1.2). 예) 부탄 최소소화농도 28 %, 최소설계농도 34 %.","src":"기출 2022-37"},{"t":"가연성가스 설계농도(보충, 표는 원문 이미지로 텍스트 미확인): 메탄·부탄 34 %, 프로판·이소부탄 36 %, 에탄 40 %, 에틸렌 49 %, 산화에틸렌 53 %, 일산화탄소 64 %, 아세틸렌 66 %, 수소 75 %.","src":"보충"}]},{"머리":"저장용기 설치장소·충전비","줄":[{"t":"저장용기 설치장소: 방호구역 외의 장소(방호구역 내라면 피난구 부근), 온도 40 ℃ 이하이고 온도변화가 작은 곳, 직사광선·빗물 침투 우려가 없는 곳, 방화문으로 구획된 실. 용기 간격 3 ㎝ 이상.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.1.1"},{"t":"저장용기와 집합관 사이 연결배관에 체크밸브를 설치한다. 다만 저장용기가 하나의 방호구역만 담당하면 제외.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.1.1.7"},{"t":"충전비: 고압식 1.5 이상 1.9 이하, 저압식 1.1 이상 1.4 이하.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.1.2.1"},{"t":"저압식 저장용기: 내압시험압력의 0.64배~0.8배에서 작동하는 안전밸브와 0.8배~내압시험압력에서 작동하는 봉판을 설치.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.1.2.2"},{"t":"저압식 저장용기: 액면계 및 압력계와 2.3 ㎫ 이상 1.9 ㎫ 이하에서 작동하는 압력경보장치를 설치.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.1.2.3"},{"t":"저압식 저장용기: 용기 내부 온도 -18 ℃ 이하에서 2.1 ㎫을 유지할 수 있는 자동냉동장치를 설치.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.1.2.4"},{"t":"내압시험압력: 고압식 25 ㎫ 이상, 저압식 3.5 ㎫ 이상.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.1.2.5"},{"t":"개방밸브는 전기식·가스압력식 또는 기계식으로 자동 개방되고 수동으로도 개방되며 안전장치가 부착된 것.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.1.3"},{"t":"저장용기와 선택밸브(또는 개폐밸브) 사이 안전장치는 배관의 최소사용설계압력과 최대허용압력 사이에서 작동. 소화가스는 전용배관으로 건축물 외부로 배출. 안전장치로 용전식은 쓸 수 없다.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.1.4"}]},{"머리":"용기 수 계산","줄":[{"t":"병당 충전량 = 용기 내용적 ÷ 충전비. 필요 병수 = 약제량 ÷ 병당 충전량(올림).","src":"기출 2024-41"},{"t":"예) 충전비 1.6, 68 L: 68 ÷ 1.6 = 42.5 kg/병, 230 kg ÷ 42.5 = 5.4 → 6병.","src":"기출 2024-41"},{"t":"예) 600 kg, 68 L: 정답 15병은 충전비 1.6~1.7 정도를 적용했을 때 나온다(문항에 충전비 조건 누락, 추정). 충전비 1.7이면 40 kg/병 → 15병.","src":"기출 2021-40"}]},{"머리":"약제 저장량(전역방출·표면화재)","줄":[{"t":"전역방출 표면화재(가연성 액체·가스 등): 방호구역 체적 1 ㎥당 표의 양. 표의 양이 최저한도 미만이면 최저한도의 양으로 한다.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.2.1.1.1"},{"t":"표 값(보충, 표는 원문 이미지로 텍스트 미확인): 45 ㎥ 미만 1.00 kg/㎥(최저 45 kg), 45~150 ㎥ 0.90 kg/㎥(최저 45 kg), 150~1,450 ㎥ 0.80 kg/㎥(최저 135 kg), 1,450 ㎥ 이상 0.75 kg/㎥(최저 1,125 kg).","src":"보충"},{"t":"설계농도가 34 % 이상인 방호대상물은 기본 소화약제량에 그림의 보정계수를 곱한다.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.2.1.1.2"},{"t":"개구부에 자동폐쇄장치를 설치하지 않은 경우: 개구부면적 1 ㎡당 5 ㎏을 가산한다. 개구부 면적은 방호구역 전체 표면적의 3 % 이하.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.2.1.1.3"}]},{"머리":"약제 저장량(전역방출·심부화재)","줄":[{"t":"심부화재(종이·목재·석탄·섬유류·합성수지류): 방호구역 체적 1 ㎥에 대하여 표의 양 이상.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.2.1.2.1"},{"t":"개구부에 자동폐쇄장치가 없으면 개구부 면적 1 ㎡당 10 ㎏을 가산한다. 개구부 면적은 방호구역 전체 표면적의 3 % 이하.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.2.1.2.2"},{"t":"표 값(보충, 표는 원문 이미지로 텍스트 미확인): 종이·목재·석탄·섬유류·합성수지류 1.3 kg/㎥(설계농도 50 %), 전기설비 1.3 kg/㎥(55 ㎥ 미만은 1.6 kg/㎥, 50 %), 서고·전자제품창고·목재가공품창고·박물관 2.0 kg/㎥(65 %), 고무류·면화류 창고·모피창고·석탄창고·집진설비 2.7 kg/㎥(75 %).","src":"보충"},{"t":"예) 서고 80 ㎥, 개구부에 자동개폐장치가 있음 → 2.0 × 80 = 160 kg(가산 없음).","src":"기출 2024-37"}]},{"머리":"약제 저장량(국소방출·호스릴)","줄":[{"t":"국소방출: 계산한 양에 고압식은 1.4, 저압식은 1.1을 곱한 양 이상.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.2.1.3"},{"t":"윗면이 개방된 용기에 저장하는 경우, 화재 시 연소면이 한정되고 가연물이 비산할 우려가 없는 경우: 방호대상물 표면적 1 ㎡당 13 ㎏.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.2.1.3.1"},{"t":"그 외: 방호공간(방호대상물 각 부분으로부터 0.6 m 거리로 둘러싸인 공간) 체적 1 ㎥당 Q = 8 − 6a/A (kg/㎥). a는 방호대상물 주위 벽 면적의 합계, A는 방호공간 벽 면적의 합계.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.2.1.3.2"},{"t":"호스릴이산화탄소소화설비는 하나의 노즐에 대하여 90 ㎏ 이상. 노즐은 20 ℃에서 노즐마다 60 ㎏/min 이상 방출. 호스접결구까지 수평거리 15 m 이하.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.2.1.4, 2.7.4"},{"t":"호스릴 설치 장소: 지상 1층·피난층으로서 개구부 유효면적 합계가 바닥면적의 15 % 이상인 부분, 또는 전기설비·화기 사용 부분의 바닥면적이 구획 바닥면적의 5분의 1 미만인 부분. 차고·주차 용도는 제외.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.7.3"}]},{"머리":"배관 방출시간","줄":[{"t":"전역방출 표면화재 방호대상물: 1분 이내에 방사.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.5.2.1"},{"t":"전역방출 심부화재 방호대상물: 7분 이내에 방사. 이 경우 설계농도가 2분 이내에 30 %에 도달해야 한다.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.5.2.2"},{"t":"국소방출: 30초 이내.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.5.2.3"},{"t":"분사헤드 방출압력: 2.1 ㎫(저압식 1.05 ㎫) 이상.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.7.1.2"}]},{"머리":"배관·기동·경보","줄":[{"t":"배관은 전용으로 한다. 강관은 압력배관용탄소강관(KS D 3562) 스케줄 80 이상(저압식 스케줄 40 이상). 호칭구경 20 ㎜ 이하는 스케줄 40 이상 가능.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.5.1"},{"t":"동관은 고압식 16.5 ㎫ 이상, 저압식 3.75 ㎫ 이상의 압력에 견딜 것. 배관부속 최소사용설계압력: 고압식 1차측 9.5 ㎫, 고압식 2차측과 저압식 4.5 ㎫.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.5.1"},{"t":"저장용기와 선택밸브 사이 집합배관에 수동잠금밸브를 설치하되 선택밸브 직전에 설치한다.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.5.3"},{"t":"수동식 기동장치: 방호구역마다, 출입구 부근 등 피난이 쉬운 곳, 조작부는 바닥에서 0.8 m 이상 1.5 m 이하, 방출지연스위치 설치.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.3.1"},{"t":"전기식 기동장치로 7병 이상의 저장용기를 동시에 개방하는 설비는 2병 이상에 전자 개방밸브를 부착한다. 가스압력식 기동용가스용기: 25 ㎫ 이상 압력에 견딜 것, 5 L 이상, 질소 등은 6.0 ㎫ 이상(21 ℃) 충전.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.3.2"},{"t":"감지기 회로는 교차회로방식으로 설치한다.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.9.1.2"},{"t":"음향경보장치는 약제 방출개시 후 1분 이상 경보를 계속한다. 확성기까지 수평거리 25 m 이하.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.10"},{"t":"분사헤드 설치제외 장소: 방재실·제어실 등 사람이 상시 근무하는 장소, 니트로셀룰로스·셀룰로이드제품 등 자기연소성물질 저장·취급 장소, 나트륨·칼륨·칼슘 등 활성금속물질 저장·취급 장소, 전시장 등 다수인이 출입·통행하는 통로·전시실.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.8.1"},{"t":"비상전원은 20분 이상 작동. 자동폐쇄장치, 배출설비(지하층·무창층·밀폐된 거실), 과압배출구, 부취발생기(2024.8.1. 신설)를 설치한다.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.11~2.16"},{"t":"이산화탄소소화약제는 소화약제의 형식승인 및 제품검사의 기술기준 적용 대상에서 제외된다.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제1조"}]}],"함정":[{"x":"전역방출방식에 있어서 종이, 목재, 석탄, 섬유류, 합성수지류 등 심부화재 방호대상물의 경우에는 10분 내에 방사될 수 있는 것으로 하여야 한다.","o":"7분 이내(설계농도가 2분 이내에 30 %).","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.5.2.2"},{"x":"국소방출 방식의 경우에는 1분 내에 방사될 수 있는 것으로 하여야 한다.","o":"국소방출은 30초 이내.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.5.2.3"},{"x":"전역방출방식에 있어서 심부화재 방호대상물의 경우에는 설계농도가 3분 이내에 40 %에 도달하여야 한다.","o":"설계농도가 2분 이내에 30 %에 도달.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.5.2.2"},{"x":"저압식 저장용기에는 액면계 및 압력계와 1.9 MPa 이상 1.5 MPa 이하의 압력에서 작동하는 압력경보장치를 설치할 것.","o":"2.3 MPa 이상 1.9 MPa 이하.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.1.2.3"},{"x":"(2023-37) 심부화재: ㄱ 5분, ㄴ 50 % 등 다른 조합","o":"ㄱ 7분, ㄴ 30 %.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.5.2.2"},{"x":"(2026-39) 심부화재: 5분, 설계농도 1분 이내 30 % 또는 5분, 2분 이내 20 % 또는 7분, 1분 이내 20 %","o":"7분 이내, 설계농도가 2분 이내에 30 %.","src":"이산화탄소소화설비의 화재안전기술기준(NFTC 106) 2.5.2.2"},{"x":"금속분화재에 사용 시 질식·냉각소화의 효과가 있다.","o":"금속분화재에는 사용할 수 없다.","src":"기출 2025-41"}]},"#10":{"묶음":[{"머리":"할론 소화약제 명명과 화학식","줄":[{"t":"할론 번호 규칙: 탄소(C) 수, 불소(F) 수, 염소(Cl) 수, 브롬(Br) 수 순서.","src":"보충"},{"t":"할론 1301: CF₃Br(브로모트리플루오로메탄). 할론 1211: CF₂ClBr. 할론 2402: C₂F₄Br₂. 할론 1011: CH₂ClBr. 할론 104: CCl₄.","src":"기출 2023-40"},{"t":"할론 2402는 에테인(ethane, C₂) 유도체다.","src":"기출 2023-40"},{"t":"상온·상압의 상태: 할론 1301은 기체, 할론 1211은 기체(액화 용이), 할론 2402는 액체.","src":"보충"},{"t":"오존파괴지수(ODP): 할론 1301 약 10, 할론 2402 약 6, 할론 1211 약 3. 할론 1301이 가장 크다.","src":"기출 2023-40"},{"t":"주된 소화효과는 억제소화(부촉매, 연쇄반응 차단). 할로겐 원소의 소화효과 크기는 I > Br > Cl > F, 안정성은 반대.","src":"기출 2023-40"},{"t":"CF₃Br(할론 1301)의 주된 소화방법은 억제소화.","src":"기출 2024-36"}]},{"머리":"할로겐화합물 및 불활성기체 소화약제 정의","줄":[{"t":"할로겐화합물 및 불활성기체소화약제: 할로겐화합물(할론 1301, 할론 2402, 할론 1211 제외) 및 불활성기체로서 전기적으로 비전도성이며 휘발성이 있거나 증발 후 잔여물을 남기지 않는 소화약제.","src":"할로겐화합물 및 불활성기체소화설비의 화재안전성능기준(NFPC 107A) 제3조제1호"},{"t":"할로겐화합물소화약제: 불소, 염소, 브롬 또는 요오드 중 하나 이상의 원소를 포함하는 유기화합물을 기본성분으로 하는 소화약제.","src":"할로겐화합물 및 불활성기체소화설비의 화재안전성능기준(NFPC 107A) 제3조제2호"},{"t":"불활성기체소화약제: 헬륨, 네온, 아르곤 또는 질소가스 중 하나 이상의 원소를 기본성분으로 하는 소화약제.","src":"할로겐화합물 및 불활성기체소화설비의 화재안전성능기준(NFPC 107A) 제3조제3호"},{"t":"충전밀도: 소화약제의 중량과 저장용기 내부 용적의 비(중량/용적). 충전비와 반대.","src":"할로겐화합물 및 불활성기체소화설비의 화재안전성능기준(NFPC 107A) 제3조제4호"},{"t":"설계농도: 소화농도에 안전율을 고려한 농도. 최대허용 설계농도: 사람이 상주하는 곳에 적용하는, 인체 안전에 영향을 미치지 않는 농도.","src":"할로겐화합물 및 불활성기체소화설비의 화재안전성능기준(NFPC 107A) 제3조"},{"t":"설계농도(%) = 소화농도(%) × A·B·C급 화재별 안전계수 이상. 사람이 상주하는 곳은 최대허용 설계농도를 초과할 수 없다.","src":"할로겐화합물 및 불활성기체소화설비의 화재안전성능기준(NFPC 107A) 제7조"}]},{"머리":"소화약제 종류별 화학식·계열","줄":[{"t":"HFC-23: CHF₃. HFC-125: CHF₂CF₃. HFC-227ea: CF₃CHFCF₃. HFC-236fa: CF₃CH₂CF₃.","src":"기출 2022-38"},{"t":"HCFC-124: CHClFCF₃. HCFC 계열이다(HFC 계열이 아니다).","src":"기출 2022-38"},{"t":"FC-3-1-10: C₄F₁₀ (퍼플루오로부탄). FK-5-1-12: 도데카플루오로-2-메틸펜탄-3-온(불소·탄소·산소로 구성). FIC-13I1: 트리플루오로요다이드(CF₃I).","src":"소화약제의 형식승인 및 제품검사의 기술기준 제8조"},{"t":"혼합 약제: HCFC BLEND A(HCFC-22 82 wt%, HCFC-124 9.5 wt%, HCFC-123 4.75 wt%, 이소프로페닐-1-메틸시이클로헥센 3.75 wt%). HFC BLEND B(HFC-134a 86 wt%, HFC-125 9.0 wt%, 이산화탄소 5 wt%).","src":"소화약제의 형식승인 및 제품검사의 기술기준 제8조"},{"t":"순도: HCFC-124, HFC-125, HFC-227ea, HFC-23, 할론 1211, HFC-236fa, FIC-13I1, FK-5-1-12는 99.0 mol% 이상. 할론 1301은 99.6 mol% 이상.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제8조"}]},{"머리":"불활성기체 소화약제 조성","줄":[{"t":"IG-541: 질소 52±4 vol%, 아르곤 40±4 vol%, 이산화탄소 8~9 vol%. 헬륨은 포함되지 않는다.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제9조"},{"t":"IG-01: 아르곤 99.9 vol% 이상. IG-100: 질소 99.9 vol% 이상. IG-55: 질소 50±5 vol%, 아르곤 50±5 vol%.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제9조"}]},{"머리":"최대허용 설계농도","줄":[{"t":"최대허용 설계농도(보충, 원문 제4조 표는 이미지라 텍스트 미확인): HCFC-124 1.0 %, HFC-125 11.5 %, HFC-227ea 10.5 %, HFC-23 30 %, HFC-236fa 12.5 %, FIC-13I1 0.3 %, FK-5-1-12 10 %, FC-3-1-10 40 %, HCFC BLEND A 10 %.","src":"보충"},{"t":"불활성기체(IG-01, IG-100, IG-541, IG-55)의 최대허용 설계농도는 43 %(보충, 원문 표 이미지로 텍스트 미확인).","src":"보충"},{"t":"2022 기출: HCFC-124 1.0 %, HFC-236fa 12.5 %, HFC-23 30 %는 옳은 선지, IG-100 30 %는 틀린 선지.","src":"기출 2022-41"}]},{"머리":"오존파괴지수","줄":[{"t":"ODP가 0인 할로겐화합물 소화약제: HFC-23, FC-3-1-10, FK-5-1-12. HCFC-124는 염소를 포함하여 ODP가 0이 아니다.","src":"기출 2024-42"},{"t":"FK-5-1-12는 오존층 파괴 등 환경오염에 미치는 영향이 적다.","src":"기출 2025-39"}]},{"머리":"FK-5-1-12의 특성","줄":[{"t":"구성원소는 플루오르, 탄소, 산소. 물보다 빨리 기화되어 연쇄반응 차단과 냉각소화를 한다.","src":"기출 2025-39"},{"t":"플루오르화수소(HF)의 발생량은 화염의 크기, 소화농도, 화재진압시간에 비례한다.","src":"기출 2025-39"},{"t":"할로겐화합물소화약제는 10초 이내에 방호구역 각 부분에 최소설계농도의 95 % 이상에 해당하는 약제량이 방출되어야 한다.","src":"할로겐화합물 및 불활성기체소화설비의 화재안전성능기준(NFPC 107A) 제10조제3항"}]},{"머리":"저장용기","줄":[{"t":"저장용기는 방호구역 외의 장소로서 방화구획된 실에 설치한다.","src":"할로겐화합물 및 불활성기체소화설비의 화재안전성능기준(NFPC 107A) 제6조제1항"},{"t":"동일 집합관에 접속되는 저장용기는 동일한 내용적을 가진 것으로 충전량과 충전압력이 같도록 한다.","src":"할로겐화합물 및 불활성기체소화설비의 화재안전성능기준(NFPC 107A) 제6조제2항제2호"},{"t":"저장용기의 약제량 손실이 5 %를 초과하거나 압력손실이 10 %를 초과하면 재충전하거나 교체한다. 다만 불활성기체 소화약제 저장용기는 압력손실이 5 %를 초과하면 재충전하거나 교체한다.","src":"할로겐화합물 및 불활성기체소화설비의 화재안전성능기준(NFPC 107A) 제6조제2항제3호"},{"t":"저장용기와 선택밸브(또는 개폐밸브) 사이에 과압방지 안전장치를 설치하고, 안전장치로 나온 소화가스는 전용배관으로 건축물 외부로 배출한다.","src":"할로겐화합물 및 불활성기체소화설비의 화재안전성능기준(NFPC 107A) 제6조제4항"},{"t":"방출경로 배관의 내용적 비율이 제조업체 설계기준 값 이상이면 해당 방호구역은 별도 독립방식으로 한다.","src":"할로겐화합물 및 불활성기체소화설비의 화재안전성능기준(NFPC 107A) 제6조제3항"}]},{"머리":"약제량 산정","줄":[{"t":"할로겐화합물소화약제: W = V/S × C/(100 − C). W 약제량(kg), V 방호구역 체적(㎥), S 소화약제별 비체적(㎥/kg), C 설계농도(%). S = K₁ + K₂·t.","src":"보충"},{"t":"불활성기체소화약제: X = 2.303 × (V_s/S) × log₁₀[100/(100 − C)]. V_s 20 ℃ 비체적.","src":"보충"},{"t":"방호구역이 둘 이상이면 가장 큰 방호구역에 대하여 산출한 양 이상으로 한다(별도 독립방식 대상 아닌 경우).","src":"할로겐화합물 및 불활성기체소화설비의 화재안전성능기준(NFPC 107A) 제7조제3항"}]},{"머리":"배관·분사헤드·기타","줄":[{"t":"배관 구경: 할로겐화합물소화약제는 10초 이내, 불활성기체소화약제는 A·C급 화재 2분, B급 화재 1분 이내에 최소설계농도의 95 % 이상에 해당하는 약제량이 방출되도록 한다.","src":"할로겐화합물 및 불활성기체소화설비의 화재안전성능기준(NFPC 107A) 제10조제3항"},{"t":"분사헤드 설치높이: 방호구역 바닥으로부터 0.2 m 이상 3.7 m 이하. 천장높이가 3.7 m를 초과하면 추가로 다른 열의 분사헤드를 설치.","src":"할로겐화합물 및 불활성기체소화설비의 화재안전성능기준(NFPC 107A) 제12조제1항"},{"t":"분사헤드 오리피스 면적은 연결 배관구경 면적의 70 % 이하.","src":"할로겐화합물 및 불활성기체소화설비의 화재안전성능기준(NFPC 107A) 제12조제3항"},{"t":"음향경보는 방출 개시 후 1분 이상 계속. 비상전원은 20분 이상 작동. 자동식 기동장치의 감지기 회로는 교차회로방식.","src":"할로겐화합물 및 불활성기체소화설비의 화재안전성능기준(NFPC 107A) 제13조, 제14조, 제16조"},{"t":"설치제외: 사람이 상주하는 곳으로 최대허용 설계농도를 초과하는 장소, 소화성능이 인정되지 않는 위험물을 저장·보관·사용하는 장소.","src":"할로겐화합물 및 불활성기체소화설비의 화재안전성능기준(NFPC 107A) 제5조"}]},{"머리":"약제와 주된 소화방법","줄":[{"t":"합성계면활성제포는 질식·냉각 효과를 낸다.","src":"보충"},{"t":"할로겐화합물소화약제(HFC 계열 등)는 냉각과 일부 화학적(억제) 효과를 낸다. 기출 2024-36은 CF₃Br을 억제소화의 옳은 연결로, HFC-125와 NH₄H₂PO₄의 연결을 틀린 연결로 출제했다.","src":"기출 2024-36"},{"t":"제3종 분말(NH₄H₂PO₄)은 냉각·질식·방진·탈수탄화·부촉매 등 복합 효과를 낸다.","src":"기출 2024-39"}]}],"함정":[{"x":"불활성기체 소화약제 IG-541에는 He(헬륨)이 포함된다.","o":"IG-541은 질소·아르곤·이산화탄소로 구성되며 헬륨은 없다.","src":"소화약제의 형식승인 및 제품검사의 기술기준 제9조"},{"x":"CHClFCF3는 HFC 계열이다.","o":"CHClFCF₃는 HCFC-124로 HCFC 계열이다.","src":"기출 2022-38"},{"x":"IG-100의 최대허용 설계농도: 30 %","o":"IG-100의 최대허용 설계농도는 43 %(보충).","src":"기출 2022-41"},{"x":"할론 1211의 화학식은 CF3ClBr이다.","o":"할론 1211은 CF₂ClBr이다(CF₃Br은 할론 1301).","src":"기출 2023-40"},{"x":"오존파괴지수는 할론 1211이 할론 1301보다 크다.","o":"할론 1301(약 10)이 할론 1211(약 3)보다 크다.","src":"기출 2023-40"},{"x":"할론 1301은 상온과 상압에서 액체이며, 주된 소화효과는 억제소화이다.","o":"할론 1301은 상온·상압에서 기체이고 주된 소화효과가 억제소화이다.","src":"기출 2023-40"},{"x":"합성계면활성제포 - 냉각소화","o":"출제 오답(합성계면활성제포의 주된 효과는 질식, 정답키 기준)","src":"기출 2024-36"},{"x":"CHF2CF3 - 냉각소화","o":"출제 오답(정답키는 CF₃Br - 억제소화만 옳은 연결로 처리)","src":"기출 2024-36"},{"x":"NH4H2PO4 - 억제소화","o":"출제 오답(정답키는 CF₃Br - 억제소화만 옳은 연결로 처리)","src":"기출 2024-36"},{"x":"할로겐화합물 소화약제 중 오존파괴지수(ODP)가 0인 소화약제가 아닌 것: HFC-23, FC-3-1-10, FK-5-1-12","o":"이 세 약제는 ODP 0이다. ODP가 0이 아닌 약제는 HCFC-124.","src":"기출 2024-42"},{"x":"FK-5-1-12 소화약제는 1분 이내에 95% 이상 해당하는 약제량이 방출되도록 하여야한다.","o":"10초 이내에 최소설계농도의 95 % 이상이 방출되어야 한다.","src":"할로겐화합물 및 불활성기체소화설비의 화재안전성능기준(NFPC 107A) 제10조제3항"},{"x":"2023-36: 약제량 손실 10퍼센트, 압력손실 10퍼센트 등 다른 조합 (ㄱ 10, ㄴ 15, ㄷ 10 등)","o":"약제량 손실 5 %, 압력손실 10 %, 불활성기체는 압력손실 5 %.","src":"할로겐화합물 및 불활성기체소화설비의 화재안전성능기준(NFPC 107A) 제6조제2항제3호"}]},"#11":{"묶음":[{"머리":"옴의 법칙·저항","줄":[{"t":"옴의 법칙: V = IR. 저항 R = ρℓ/A (저항률 ρ, 길이 ℓ, 단면적 A). 저항은 길이에 비례하고 단면적에 반비례한다.","src":"기출 2026-42"},{"t":"저항률(resistivity)의 단위는 Ω·m이다(Ω/m가 아님).","src":"기출 2026-42"},{"t":"도체는 온도가 오르면 저항이 증가한다. 절연체와 반도체는 온도가 오르면 저항이 감소한다.","src":"기출 2026-42"},{"t":"액체 형태의 절연체도 존재한다(예: 절연유).","src":"기출 2026-42"},{"t":"직렬 합성저항 R = R₁ + R₂ + …, 병렬 합성 1/R = 1/R₁ + 1/R₂ + …","src":"보충"}]},{"머리":"회로 해석(분압·브리지)","줄":[{"t":"브리지 평형: 마주 보는 변 저항의 곱이 같으면(R₁R₄ = R₂R₃) 가운데 저항에 전류가 흐르지 않는다. 가운데 저항은 무시하고 합성한다.","src":"기출 2023-43"},{"t":"예) 10 V, 상단 3 Ω·3 Ω, 하단 1 Ω·1 Ω, 가운데 3 Ω: 3:1 = 3:1로 평형 → (3+1)와 (3+1)의 병렬 = 2 Ω → I = 10 ÷ 2 = 5 A.","src":"기출 2023-43"},{"t":"직렬회로의 전압은 저항비로 나뉜다(분압). 전체 저항비에서 한 부분의 전압을 알면 나머지를 비례로 구한다.","src":"기출 2024-49"},{"t":"키르히호프 전류법칙(KCL): 한 점으로 들어오는 전류의 합 = 나가는 전류의 합. 전압법칙(KVL): 폐회로의 전압 상승의 합 = 전압 강하의 합.","src":"보충"}]},{"머리":"정전용량(콘덴서)","줄":[{"t":"정전용량 C = Q/V. 평행판 콘덴서 C = εA/d. 저장 에너지 W = ½CV².","src":"보충"},{"t":"직렬 접속: 합성 정전용량 1/C = 1/C₁ + 1/C₂ + … 으로 감소한다. 전하량 Q는 모두 같고 전압은 정전용량에 반비례하여 나뉜다(정전용량이 작은 콘덴서에 전압이 많이 걸린다).","src":"기출 2024-43"},{"t":"병렬 접속: 합성 정전용량 C = C₁ + C₂ + … 이고 총 전하량은 각 콘덴서 전하량의 합과 같다.","src":"기출 2024-43"},{"t":"직렬 풀이 순서: 합성 C → Q = C_합성·V → 개별 전압 V_i = Q/C_i. 예) 2, 3, 5 μF, 800 V: C = 0.9677 μF, Q = 774 μC → C₂ 전압 = 774 ÷ 3 = 258 V.","src":"기출 2025-44"},{"t":"같은 용량 n개 직렬은 C/n. 예) 300 μF 3개 직렬 = 100 μF.","src":"기출 2026-44"}]},{"머리":"전계와 전기력선","줄":[{"t":"쿨롱의 법칙: F = q₁q₂ ÷ (4πε₀r²) = 9×10⁹ q₁q₂/r². 자기 쿨롱 법칙도 같은 형태.","src":"기출 2022-45"},{"t":"전기력선의 성질: 정전하에서 나와 부전하로 들어간다. 서로 교차하지 않는다. 등전위면과 직교한다. 도체 표면에 수직이다. 밀도는 전계의 세기와 같다. 접선 방향이 전계의 방향과 일치한다.","src":"기출 2021-46"},{"t":"완전 도체: 전하는 도체 표면에만 분포하고 내부에는 없다. 내부 전기장은 0이다. 표면은 등전위면이고 내부 전위는 표면 전위와 같다. 표면에서 전기장은 표면에 수직이다.","src":"기출 2023-44"},{"t":"전자장 해석의 미분연산: ∇V는 스칼라 함수의 변화율(경도, gradient). 벡터 E의 발산(divergence)은 단위 체적에서 발산하는 선속수로 ∇·E로 표시. 회전은 ∇×E. 라플라시안은 ∇·∇ = ∇².","src":"기출 2022-44"}]},{"머리":"열전효과","줄":[{"t":"제벡 효과(Seebeck): 이종 금속을 접합하여 폐회로를 만들고 두 접합점의 온도를 다르게 하면 열기전력이 생겨 열전류가 흐르는 현상.","src":"기출 2021-47"},{"t":"펠티에 효과(Peltier): 서로 다른 금속으로 된 폐회로에 온도를 일정하게 두고 직류 전류를 흘리면 접합부에서 열의 발생 또는 흡수가 일어나는 현상.","src":"기출 2025-43"},{"t":"톰슨 효과(Thomson): 동종 금속 도선의 두 점 사이에 온도차를 주고 전류를 흘리면 줄열 외에 열의 발생 또는 흡수가 일어나는 현상.","src":"기출 2024-44"},{"t":"핀치 효과(Pinch): 도체에 큰 전류를 흘리면 전류 자신이 만드는 자기력으로 도체가 수축하는 현상.","src":"기출 2021-47"},{"t":"기억: 열 → 전기(제벡), 전기 → 접합부 열(펠티에), 동종 금속 온도차(톰슨).","src":"보충"}]},{"머리":"자기: 자기력선·자속·법칙","줄":[{"t":"자기력선: 서로 교차하지 않는다. 자계의 방향은 자기력선 위 한 점에서의 접선 방향. 밀도는 자계의 세기와 같다. 자석 외부는 N극에서 나와 S극으로 들어가고 내부는 S극에서 N극으로 향한다.","src":"기출 2024-45"},{"t":"자속밀도: 자속의 방향에 수직인 단위 면적을 통과하는 자속의 수(B = Φ/A).","src":"기출 2022-45"},{"t":"전자력의 방향(도체에 전류를 흘릴 때 자기장 속에서 받는 힘): 플레밍의 왼손 법칙(전동기). 엄지 힘, 검지 자계, 중지 전류.","src":"기출 2024-46"},{"t":"유도기전력의 방향(도체의 운동으로 생기는 기전력): 플레밍의 오른손 법칙(발전기). 렌츠의 법칙은 유도기전력이 자속 변화를 방해하는 방향.","src":"기출 2022-45"},{"t":"암페어의 주회법칙(∮H·dℓ = I)은 전류에 의한 자계의 세기를 구하는 데 사용한다. 암페어의 오른나사 법칙은 전류와 자계 방향 관계.","src":"기출 2022-45"},{"t":"평행 도체 사이의 힘: F = μ₀I₁I₂ ÷ (2πd) (N/m). 같은 방향 전류는 인력, 반대 방향은 척력. 예) 2 m, 1 A, 1 A → μ₀ ÷ 4π, 인력.","src":"기출 2023-46"}]},{"머리":"전자유도·인덕턴스","줄":[{"t":"유도기전력 e = N·ΔΦ/Δt = M·ΔI/Δt (크기). 코일 감은 수 N, 자속 변화 ΔΦ, 상호인덕턴스 M.","src":"기출 2026-45"},{"t":"예) 500회, 0.8 Wb → 0.6 Wb, 0.5초: e = 500 × 0.2 ÷ 0.5 = 200 V.","src":"기출 2026-45"},{"t":"예) M 150 mH, 5 A → 20 A, 0.5초: e = 0.15 × 15 ÷ 0.5 = 4.5 V.","src":"기출 2021-48"},{"t":"자기인덕턴스 L = μN²A/ℓ. 코일 안에 삽입된 물질의 투자율에 비례한다.","src":"기출 2023-45"},{"t":"동일 인덕턴스 2개 직렬(상호결합 없음) 합성 인덕턴스는 2배.","src":"기출 2023-45"},{"t":"인덕터 저장 에너지 W = ½LI². 전류가 일정하면 인덕턴스에 비례한다.","src":"기출 2023-45"},{"t":"인덕턴스는 전류 변화를 방해하는 정도를 나타내는 비례상수. 전하를 축적하는 능력은 정전용량이다.","src":"기출 2023-45"}]},{"머리":"과도현상(RL 회로)","줄":[{"t":"RL 회로 시정수 τ = L/R. 전류·전압 응답 y(t) = y(∞) + [y(0) − y(∞)]·e^(−t/τ).","src":"기출 2023-48"},{"t":"풀이 순서: 스위치 개방 전 정상상태에서 초기값 → 개방 후 정상상태에서 최종값 → τ를 구해 대입. 정답 5 − (1/3)e^(−2t)는 최종값 5 V, τ = 0.5초(L 2 H, R 4 Ω)인 경우.","src":"기출 2023-48"}]},{"머리":"2포트 회로(어드미턴스 파라미터)","줄":[{"t":"Y₁₁ = I₁/V₁ (V₂ = 0), Y₁₂ = I₁/V₂ (V₁ = 0), Y₂₁ = I₂/V₁ (V₂ = 0), Y₂₂ = I₂/V₂ (V₁ = 0).","src":"기출 2023-49"},{"t":"1 Ω 저항 3개의 T형 회로: Y₁₁ = Y₂₂ = 2/3 S, Y₁₂ = Y₂₁ = −1/3 S. 상반 회로라 Y₁₂ = Y₂₁.","src":"기출 2023-49"}]}],"함정":[{"x":"전기력선의 방향은 전계의 방향과 일치하지 않는다.","o":"전기력선의 접선 방향이 전계의 방향과 일치한다.","src":"기출 2021-46"},{"x":"전하는 도체 내부에 균일하게 분포한다.","o":"전하는 완전 도체의 표면에만 분포한다.","src":"기출 2023-44"},{"x":"전자장 해석: 벡터 E 의 발산은 ∇²∙E 로 표시한다.","o":"발산은 ∇·E로 표시한다(∇²은 라플라시안).","src":"기출 2022-44"},{"x":"도체의 운동에 의한 전자유도현상에 의해 발생되는 유도기전력의 방향은 플레밍의 왼 손법칙에 따라 결정된다.","o":"유도기전력의 방향은 플레밍의 오른손 법칙.","src":"기출 2022-45"},{"x":"코일이 전하를 축적할 수 있는 능력의 정도를 나타내는 비례상수이다(자기 인덕턴스).","o":"전하 축적 능력은 정전용량. 인덕턴스는 자속과 전류의 비례상수.","src":"기출 2023-45"},{"x":"직렬 접속 시 정전용량이 큰 콘덴서에 전압이 많이 걸린다.","o":"정전용량이 작은 콘덴서에 전압이 많이 걸린다(V ∝ 1/C).","src":"기출 2024-43"},{"x":"자기력선은 자석 내부에서는 S극에서 나와 N극으로 들어간다.","o":"출제 오답(정답키 기준 틀린 선지. 표준 설명은 자석 내부가 S극에서 N극 방향)","src":"기출 2024-45"},{"x":"도체와 절연체는 온도가 증가함에 따라 저항이 증가한다.","o":"도체는 증가, 절연체는 감소한다.","src":"기출 2026-42"},{"x":"저항의 크기는 단면적에 비례하고, 길이에 반비례한다.","o":"저항은 길이에 비례하고 단면적에 반비례한다.","src":"기출 2026-42"},{"x":"재질에 따라 고유값을 갖는 저항률(resistivity)의 단위는 [Ω/m]이다.","o":"저항률의 단위는 Ω·m.","src":"기출 2026-42"},{"x":"Y12 = 1/3","o":"Y₁₂ = −1/3 S.","src":"기출 2023-49"}]},"#12":{"묶음":[{"머리":"정현파 교류의 값","줄":[{"t":"v = Vm·sin ωt 의 실효값 V = Vm/√2. 평균값(반주기) = 2Vm/π.","src":"기출 2025-45"},{"t":"각속도 ω = 2πf. 위상 R: 전압과 전류 동상. L: 전류가 전압보다 90° 뒤진다. C: 전류가 전압보다 90° 앞선다.","src":"보충"},{"t":"리액턴스: X_L = ωL, X_C = 1/(ωC). 임피던스 Z = R + j(X_L − X_C), |Z| = √(R² + (X_L − X_C)²).","src":"기출 2026-47"}]},{"머리":"R-L 직렬 회로","줄":[{"t":"R-L 직렬회로에서 전류는 전압보다 θ = tan⁻¹(ωL/R) 만큼 뒤진다.","src":"기출 2021-43"},{"t":"R-C 직렬회로에서 전류는 전압보다 tan⁻¹(1/(ωCR)) 만큼 앞선다.","src":"보충"},{"t":"임피던스 각 θ = tan⁻¹(X/R). 역률 cosθ = R/|Z|.","src":"기출 2021-43"}]},{"머리":"R-L-C 직렬 계산","줄":[{"t":"풀이 순서: ω를 읽는다(v = √2·V·sin(ωt)에서 계수) → X_L, X_C → Z → I = V/Z. 실효값 V는 √2를 뺀 값.","src":"기출 2026-47"},{"t":"예) v = √2·100·sin(500t), R 40 Ω, C 100 μF, L 100 mH: X_L = 50 Ω, X_C = 20 Ω, Z = √(40² + 30²) = 50 Ω → I = 100 ÷ 50 = 2 A.","src":"기출 2026-47"},{"t":"직렬 공진: X_L = X_C, 공진주파수 f = 1/(2π√(LC)), 이때 Z = R(최소), 전류 최대, 역률 1.","src":"보충"},{"t":"병렬 공진(R-L 직렬 가지에 C 병렬): 공진 시 임피던스 Z = L/(RC) (최대).","src":"기출 2024-48"}]},{"머리":"전력·역률","줄":[{"t":"피상전력 S = VI (VA), 유효전력 P = VI·cosθ (W), 무효전력 Q = VI·sinθ (Var). S² = P² + Q².","src":"기출 2025-46"},{"t":"역률 cosθ = P/S. 예) 피상 10 kVA, 무효 6 kVar → P = √(10² − 6²) = 8 kW.","src":"기출 2025-46"},{"t":"소비전력 풀이: P = V·I·cos(θ_v − θ_i), V, I는 실효값. 예) v = √2·220·sin(377t + π/3), i = √2·4·sin(377t + π/6): 위상차 π/6(30°) → P = 220 × 4 × cos30° = 440√3 W.","src":"기출 2026-48"},{"t":"R만 전력을 소비한다: P = I²R.","src":"보충"}]},{"머리":"최대 전력 전달","줄":[{"t":"전원 내부 임피던스 Zs = Rs + jXs, 부하가 순저항 R_L 하나인 경우: 부하 전력이 최대가 되는 R_L = |Zs| = √(Rs² + Xs²). 예) Zs = 4 + j3 → R_L = 5 Ω.","src":"기출 2023-47"},{"t":"부하가 복소 임피던스로 조정 가능하면 Z_L = Zs* (켤레복소수)일 때 최대 전력.","src":"보충"}]},{"머리":"비정현파(고조파) 교류","줄":[{"t":"비정현파 실효값 = √(각 고조파 실효값의 제곱합). 예) 50, 30, 10 V → √(2500 + 900 + 100) = √3500 ≈ 59 V.","src":"기출 2025-48"},{"t":"비정현파 평균전력 = 같은 차수 고조파끼리 (Vm·Im/2)·cos(θv − θi)를 모두 더한 값. 다른 차수의 곱은 평균전력에 기여하지 않는다.","src":"기출 2021-45"},{"t":"예) 기본파 100·30/2·cos60° = 750, 3고조파는 위상차 90°라 0, 5고조파 10·5/2 = 25 (cos 항은 sin으로 환산 후 위상 비교) → 합 775 W.","src":"기출 2021-45"},{"t":"음수 계수의 sin 항은 위상을 180° 이동시켜 부호를 양으로 바꾼 뒤 비교한다.","src":"기출 2021-45"}]}],"함정":[{"x":"R-L 직렬회로: 전류가 전압보다 tan^-1(R/ωL) 만큼 앞선다.","o":"전류는 전압보다 tan⁻¹(ωL/R) 만큼 뒤진다.","src":"기출 2021-43"},{"x":"R-L 직렬회로: 전류가 전압보다 tan^-1(R/ωL) 만큼 뒤진다.","o":"각은 tan⁻¹(ωL/R).","src":"기출 2021-43"},{"x":"R-L 직렬회로: 전류가 전압보다 tan^-1(ωL/R) 만큼 앞선다.","o":"L이 있으면 전류가 뒤진다.","src":"기출 2021-43"},{"x":"RLC 병렬(공진 시) 임피던스: R − 1/√LC 또는 R + 1/√LC 또는 RC/L","o":"공진 시 임피던스는 L/(RC).","src":"기출 2024-48"}]},"#13":{"묶음":[{"머리":"Y결선과 Δ결선","줄":[{"t":"Y결선: 선간전압 V_l = √3·V_p (30° 앞섬), 선전류 I_l = I_p.","src":"기출 2021-44"},{"t":"Δ결선: 선간전압 V_l = V_p, 선전류 I_l = √3·I_p (30° 뒤짐).","src":"기출 2021-44"},{"t":"예) Δ-Δ, 전원 400 V, 부하 12 + j16 Ω: |Z| = 20 Ω, 상전류 = 400 ÷ 20 = 20 A, 선전류 = 20√3 A.","src":"기출 2021-44"},{"t":"3상 전력 P = √3·V_l·I_l·cosθ = 3·V_p·I_p·cosθ.","src":"보충"}]},{"머리":"2전력계법","줄":[{"t":"유효전력 P = W₁ + W₂. 예) 800 W + 600 W = 1,400 W.","src":"기출 2026-49"},{"t":"무효전력 Q = √3·(W₁ − W₂). 피상전력 S = 2√(W₁² + W₂² − W₁W₂). 역률 cosθ = (W₁ + W₂) ÷ (2√(W₁² + W₂² − W₁W₂)).","src":"기출 2026-49"}]},{"머리":"변압기 결선","줄":[{"t":"Δ-Δ 결선: 지락사고 검출이 용이하지 않다. 변압기 1대 고장 시 V결선으로 운전 가능.","src":"기출 2025-47"},{"t":"Y-Y 결선: 고전압 결선에 적합하다(상전압이 선간전압의 1/√3).","src":"기출 2025-47"},{"t":"Δ-Y 결선: 주로 발전소에서 전압을 높여 전력전송을 위해 사용한다.","src":"기출 2025-47"},{"t":"Y-Δ 결선: 변압기 1대 고장 시 전력공급이 불가능하다.","src":"기출 2025-47"},{"t":"V결선: 단상변압기 2대로 3상 전력을 얻는 방식. 이용률 √3/2 = 86.6 %, 출력비(Δ결선 대비) 1/√3 = 57.7 %.","src":"기출 2022-47"},{"t":"V결선 출력 P_V = √3·P₁ (P₁은 변압기 1대 용량). Δ결선 변압기 3대 출력(3P₁) 대비 57.7 %.","src":"기출 2022-47"}]},{"머리":"유도전동기 기동","줄":[{"t":"농형 유도전동기 Y-Δ 기동: 기동전류는 Δ결선으로 직접 기동한 경우의 1/3.","src":"기출 2021-49"},{"t":"Δ → Y 변환 시 선전류 비 I_Y/I_Δ = 1/3 (임피던스가 같을 때).","src":"기출 2024-50"},{"t":"기동전류 제한: 농형은 Y-Δ 기동, 기동보상기법, 리액터 기동. 권선형은 2차 회로에 저항을 삽입해 기동전류를 제한한다(기동보상기법이 아님).","src":"기출 2021-49"},{"t":"분상 기동형 단상 유도전동기: 병렬로 연결된 주권선과 보조권선이 회전자계를 만들어 기동한다.","src":"기출 2021-49"},{"t":"콘덴서 기동형 단상 유도전동기: 기동권선에 직렬로 콘덴서를 연결하여 주권선과 기동권선 사이에 위상차를 만들어 기동한다.","src":"기출 2021-49"},{"t":"유도전동기 동기속도 N_s = 120f/P (rpm), 슬립 s = (N_s − N)/N_s.","src":"보충"}]}],"함정":[{"x":"권선형 유도전동기 기동 시 기동전류를 제한하기 위하여 기동보상기법이 주로 사용된다.","o":"권선형은 2차 회로에 저항을 삽입한다. 기동보상기법은 농형에 쓴다.","src":"기출 2021-49"}]},"#14":{"묶음":[{"머리":"논리회로 기본","줄":[{"t":"AND: X = A·B (둘 다 1일 때만 1). OR: X = A + B (하나라도 1이면 1). NOT: X = A̅.","src":"보충"},{"t":"NAND: X = (A·B)의 부정. NOR: X = (A + B)의 부정. XOR(배타적 논리합): X = A̅·B + A·B̅. XNOR: X = A·B + A̅·B̅.","src":"기출 2026-50"},{"t":"드모르간 정리: (A·B)의 부정 = A̅ + B̅, (A + B)의 부정 = A̅·B̅.","src":"보충"},{"t":"타임차트 읽기: A, B의 모든 조합(00, 01, 10, 11)에서 X의 값을 읽어 진리표를 만든 뒤 논리식에 대응시킨다. A, B가 서로 다를 때만 X가 1이면 XOR.","src":"기출 2026-50"}]},{"머리":"자기유지·인터록(무접점 회로)","줄":[{"t":"자기유지: 출력 접점(또는 출력)을 입력 OR로 되먹임하여, 시동 입력이 꺼져도 출력이 유지되는 회로.","src":"기출 2021-42"},{"t":"인터록(선입력 우선): 두 출력의 NOT을 서로의 AND 입력에 되먹임하여 한쪽이 동작하면 다른 쪽은 동작하지 못하게 하는 회로.","src":"기출 2021-42"},{"t":"타임차트 문항 풀이 순서: 각 출력의 논리식(자기유지 + 정지 조건 + 인터록)을 쓴다 → 입력이 변하는 시각마다 R₁, R₂를 순서대로 갱신한다. 정답은 R₁이 1~7, 21~25 구간, R₂가 9~18 구간에서 On인 선지.","src":"기출 2021-42"}]},{"머리":"블록선도","줄":[{"t":"직렬 접속: 전달함수 G = G₁·G₂. 병렬 접속: G = G₁ + G₂.","src":"보충"},{"t":"피드백(부궤환) 접속: G = G₁ ÷ (1 + G₁G₂). 정궤환은 분모 1 − G₁G₂.","src":"보충"}]}],"함정":[{"x":"X = (A의 부정) + (B의 부정)","o":"NAND(A·B의 부정) 식이다. 정답 논리식은 XOR: X = A̅·B + A·B̅.","src":"기출 2026-50"},{"x":"X = (A + B)의 부정","o":"NOR 식이다. 정답 논리식은 XOR: X = A̅·B + A·B̅.","src":"기출 2026-50"},{"x":"X = A·B + (A의 부정)·(B의 부정)","o":"XNOR 식이다. 정답 논리식은 XOR: X = A̅·B + A·B̅.","src":"기출 2026-50"}]}};
